INSERT INTO `xhs_note` VALUES (83, '564ea8f982718c1f54bb1713', 'Maggie麦吉', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31hd306163s0042le64kfi5ojeqhuplo', '', 1781086570640, 1781086570640, '68da6dc3000000000e027da5', 'video', '干货｜在家拥有录音棚音质の设备大公开！', '全都是自用，全程无广大家放心食用～\n	\n设备清单⬇️\n话筒： 铁三角AT4040\n声卡：阿波罗TWIN X\n监听耳机：AKG K72\n电脑：Macbook Pro\n录音软件：logic pro\n#声卡[话题]# #麦克风推荐[话题]# #录音[话题]# #监听耳机[话题]# #录音设备[话题]# #好用麦克风推荐[话题]# #爱乐者club[话题]# #浅弹一下[话题]#', 'http://sns-video-bd.xhscdn.com/1040g2so31n0vob4m58l042le64kfi5oj60lgmr8', 1759145411000, 1759457732000, '2万', '1.4万', '178', '848', '\"http://sns-web-i10.rednotecdn.com/202606101815/48461a5138b771638663126c9750b3db/1040g00831n0vob4ql80042le64kfi5ojo8k6ve0!nd_dft_wlteh_webp_3?src=A\"', '\"\\u58f0\\u5361,\\u9ea6\\u514b\\u98ce\\u63a8\\u8350,\\u5f55\\u97f3,\\u76d1\\u542c\\u8033\\u673a,\\u5f55\\u97f3\\u8bbe\\u5907,\\u597d\\u7528\\u9ea6\\u514b\\u98ce\\u63a8\\u8350,\\u7231\\u4e50\\u8005club,\\u6d45\\u5f39\\u4e00\\u4e0b\"', 'https://www.xiaohongshu.com/explore/68da6dc3000000000e027da5?xsec_token=ABX2daIv8M1Ov2Pefrel3cRrDdXLVKZMCbm5C_Hny3Kgc=&xsec_source=pc_search', '雅马哈 YDP165 外接设备', 'ABX2daIv8M1Ov2Pefrel3cRrDdXLVKZMCbm5C_Hny3Kgc=');
