INSERT INTO `xhs_note` VALUES (85, '65011c3c0000000006032274', 'Wawa同人社', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31n76pij56g005p813gu1m8jkukokl08', '', 1781086570724, 1781086570724, '684905040000000022005034', 'video', '孩子都萌成啥样了😭🫶🏻', '暖暖产前样已定！预计六月下旬开饭🍽️\n#10cm棉花娃娃[话题]# #暖暖[话题]# #无限暖暖[话题]# #苏暖暖[话题]# #暖暖棉花娃娃[话题]# #印花努努[话题]# #数调！你最喜欢哪个表情的暖宝宝~[投票]#', 'http://sns-video-bd.xhscdn.com/1040g2so31ij01qnr0e005p813gu1m8jkdb3a18g', 1749615876000, 1750171922000, '6460', '708', '263', '838', '\"http://sns-web-i10.rednotecdn.com/202606101815/bb737925c690e3cefe4216ea0e0488f6/1040g00831ij01qnpgc005p813gu1m8jkn2b4tbg!nd_dft_wlteh_webp_3?src=A\"', '\"10cm\\u68c9\\u82b1\\u5a03\\u5a03,\\u6696\\u6696,\\u65e0\\u9650\\u6696\\u6696,\\u82cf\\u6696\\u6696,\\u6696\\u6696\\u68c9\\u82b1\\u5a03\\u5a03,\\u5370\\u82b1\\u52aa\\u52aa\"', 'https://www.xiaohongshu.com/explore/684905040000000022005034?xsec_token=ABlmogA8ZSUYGqZMRHVG_W-igjug6ZoNGFHfFqiXi9gRo=&xsec_source=pc_search', '雅马哈 YDP165 外接设备', 'ABlmogA8ZSUYGqZMRHVG_W-igjug6ZoNGFHfFqiXi9gRo=');
INSERT INTO `xhs_note` VALUES (86, '5b3d752a11be103f926d1846', 'Unifairy', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo310ma2bi4mo004a6rmiqik626c0spit0', '', 1781086570770, 1781086570770, '66667702000000001303db53', 'normal', '🩰自学吉他Q&A｜电吉他录音·弹唱设备分享', 'Hii大家～之前发电吉他弹唱视频有很多小伙伴问关于设备和录音的问题，所以今天写一期Q&A解答一下💭\n	\n在没有效果器和声卡的情况下，如何录出清透干净的吉他和人声❓以下是我自用的设备和调音技巧介绍～（实际录音效果可以看我近期的视频，非专业，仅供参考哦）\n	\n🎸P1 & P2 关于设备：\n（1）电吉他：Fender Japan HybridII 亚麻色。淡淡的粉紫色真的非常高级耐看，音色也十分纯正，入股不亏！\n	\n（2）音箱：Yamaha Thr10II\n- 优点：内置电吉他效果器，APP，调音功能，可直连蓝牙放伴奏外录or连接电脑软件内录。\n- 缺点：个人感觉直连软件内录效果不太好，之后打算入个声卡用软件效果器尝试内录。\n	\n（3）话筒：Shure MV5电容话筒\n- 看到博主推荐直接买的，说实话一开始觉得踩雷了，因为录出来的声音效果不够明亮丝滑，比较闷。\n- 但多次磨合之后也发现了它的特别之处，特点是人声颗粒感比较重，会有一点复古留声机的感觉，以及像我这种细嗓会有压缩和加厚声音的效果。大家可以去听我近期发的弹唱视频，喜欢这种音质的话可以入hhh\n（4）视频录制：Macbook Photobooth（粗糙画质，复古感）or 手机轻颜相机 or 富士XE4相机\n	\n💻P3: 录音软件 & 调音Tips\n90%的情况下我会用苹果自带的库乐队，手机电脑皆可录音十分方便，后期给人声加一点混响和压缩，简单调下EQ即可。\n	\n有其他的问题也欢迎大家在评论区留言～over🫡\n	\n#电吉他[话题]# #吉他新手[话题]# #电吉他入门[话题]# #吉他录音[话题]# #吉他推荐[话题]# #电吉他入门推荐[话题]# #电吉他推荐[话题]# #fender[话题]#', '', 1717991170000, 1717991170000, '6384', '3158', '79', '259', '\"http://sns-web-i10.rednotecdn.com/202606101815/b157b120738c8257f127f99ce479d24b/1040g008313ro8m5shk004a6rmiqik626e52h790!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/acdc6a0ea48f07f75796928f276b423a/1040g008313ro8m5shk0g4a6rmiqik626g6mqd3o!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/24006dc040eb1253e3a4e46bd3e05743/1040g008313ro8m5shk104a6rmiqik626hug9dn0!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u5409\\u4ed6,\\u5409\\u4ed6\\u65b0\\u624b,\\u7535\\u5409\\u4ed6\\u5165\\u95e8,\\u5409\\u4ed6\\u5f55\\u97f3,\\u5409\\u4ed6\\u63a8\\u8350,\\u7535\\u5409\\u4ed6\\u5165\\u95e8\\u63a8\\u8350,\\u7535\\u5409\\u4ed6\\u63a8\\u8350,fender\"', 'https://www.xiaohongshu.com/explore/66667702000000001303db53?xsec_token=ABXUGLLLYdaKGnuF3uPa0bt60riRScKq9KO97-m2NUdFA=&xsec_source=pc_search', '雅马哈 YDP165 外接设备', 'ABXUGLLLYdaKGnuF3uPa0bt60riRScKq9KO97-m2NUdFA=');
INSERT INTO `xhs_note` VALUES (87, '63bcda000000000026012107', '沈蜜Meeco13', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31v1arfev1m005otsr809i8879cm3ee0', '', 1781086570806, 1781086570806, '66e90f970000000012011e00', 'normal', '配置一套苹果编曲设备（便携版）', '笔记本：MacBook Air 13-inch M3\n宿主：Logic Pro\n扩展坞：Belkin\n声卡：Arturia Minifuse 1\n电吉他：Fender Tele\n调音器：TC Electronic Polytune\nMidi键盘：Korg Nanokey2\nMidi键盘：Korg Microkey2 - 25keys\n麦克风：Shure SM86\n	\n扩展坞type C供电，双USB连接声卡和Midi键盘；\n	\n声卡配置1个综合输入接口，可以连卡侬线（麦克风）或大三芯/大二芯（乐器），如不考虑便携还是尽量选择多输入接口，这样乐器和麦克风不用频繁切换；\n	\nKorg Nano是用老式T型usb(mini usb)线连接，手感比较塑料，单纯考虑便携；\n	\nKorg Microkey勉强达到键盘手感，按键较窄，习惯了也还行，有条件还是选择全配重琴键的midi键盘或者合成器更舒适；\n	\n电容麦不用话放，声卡自带的48V勉强推得动，为更好的效果还是需要另配话放和幻象电源-\n	\n#音乐制作人[话题]#\n#编曲[话题]#', '', 1726549911000, 1726563817000, '5753', '4499', '120', '304', '\"http://sns-web-i10.rednotecdn.com/202606101815/34cb4f5c975f5254548f7976259d2685/1040g008317r9cndf3k005otsr809i887vfjg250!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/aeb3e0b306150e0ae0bad3787eda2d25/1040g008317r9cndf3k0g5otsr809i887sddrrpg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/b17c1c1a00fb8ac8cf0c3b7ccfb06d77/1040g008317r9cndf3k105otsr809i887orv9cgo!nd_dft_wlteh_webp_3?src=A\"', '\"\\u97f3\\u4e50\\u5236\\u4f5c\\u4eba,\\u7f16\\u66f2\"', 'https://www.xiaohongshu.com/explore/66e90f970000000012011e00?xsec_token=ABOiZPzPdR2xQ4oLbP8y6JeJBXiNmjn7gEROOSi-T3KbM=&xsec_source=pc_search', '雅马哈 YDP165 外接设备', 'ABOiZPzPdR2xQ4oLbP8y6JeJBXiNmjn7gEROOSi-T3KbM=');
