INSERT INTO `xhs_note` VALUES (92, '5f5d8e5e0000000001009690', '思酱不是酱', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3160nlma10s005nqthpf095kg6ip0ap0', '', 1781086571005, 1781087166637, '68ad4ebe000000001c03cd66', 'normal', '我的大玩具开箱', '选了一周 再也不想去琴房练琴啦 冲颜值下单 实木键盘\n特别神奇的是带耳机合没带一样的感觉！希望不要当软装[皱眉R]#雅马哈电钢[话题]# #雅马哈clp845[话题]# #练琴角落[话题]#', '', 1756188350000, 1756188351000, '2832', '1225', '196', '377', '\"http://sns-web-i10.rednotecdn.com/202606101815/c6bdb4dde63020497d4137244c3b3508/notes_pre_post/1040g3k831lktv0f3ks705nqthpf095kggar2bf8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/61b60b8e54e6f445b610ecdea43ba4ee/notes_pre_post/1040g3k831lktv0f3ks7g5nqthpf095kgul0arao!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/cd5078f7d72f7134f0184cacb3f87457/notes_pre_post/1040g3k831lktv0f3ks805nqthpf095kgfdk2aug!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/6bdf954f92a772e7fcb65d0c40751f85/notes_pre_post/1040g3k831lktv0f3ks8g5nqthpf095kgp6p3j6g!nd_dft_wlteh_webp_3?src=A\"', '\"\\u96c5\\u9a6c\\u54c8\\u7535\\u94a2,\\u96c5\\u9a6c\\u54c8clp845,\\u7ec3\\u7434\\u89d2\\u843d\"', 'https://www.xiaohongshu.com/explore/68ad4ebe000000001c03cd66?xsec_token=AB2DMKSIUuXsZVi6SHuuflOxYxhnOF_8IB6g3kRFTNMLY=&xsec_source=pc_search', '雅马哈 YDP165 外接设备', 'AB2DMKSIUuXsZVi6SHuuflOxYxhnOF_8IB6g3kRFTNMLY=');
INSERT INTO `xhs_note` VALUES (93, '5e8c41ee00000000010091af', '九系萌', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31q5borking6g5nkc87n094dfmatp1eg', '', 1781086571047, 1781086571047, '68721f09000000001502016e', 'normal', '🌟✨《海边餐厅》沉浸式恋综+经营游戏✨', '✨《海边餐厅》沉浸式恋综+经营游戏｜30天体验明星生活💕\n	\n姐妹们快看！我做了一个文字指令游戏！🎮《综艺：海边餐厅》真的真的超级好玩！\n💕\n🌟 真实到爆的明星体验：\n- 白天当主厨/服务员/经理（轮岗超有趣！）\n- 晚上和5位明星合宿（心动短信环节我尖叫！）\n- 每天营业结束还有直播互动环节🎤\n	\n💘 隐藏玩法太戳了：\n- 沙滩散步偶遇心动男嘉宾\n- 厨房帮忙时不小心碰到手（啊啊啊）\n- 每晚22:30准时收到匿名短信（猜猜是谁发的！）\n	\n🍽️ 经营部分超真实：\n- 要管食材采购（精打细算的样子像极了我双十一）\n- 处理顾客差评（遇到刁难客人真的会生气！）\n- 每周还要应对节目组的突击挑战\n	\n最绝的是❗️\n游戏里还有个7岁小NPC\n人小鬼大的样子萌化我了😭\n（她还会帮忙招揽客人！）\n	\n已经玩到第15天\n和歌手小哥哥的CP线快要成了👫\n每天最期待的就是晚上互动环节！\n	\n👉 指路：下方\n#ai文游[话题]# #文游[话题]# #AI聊天[话题]# #文字游戏[话题]# #一般向游戏[话题]# #模拟经营[话题]# #我和AI有话说[话题]# #ai游戏[话题]# #Deepseek[话题]##deepseek指令[话题]# #chatbox[话题]##chatgpt[话题]##Claude[话题]##deepseek[话题]##剧情向[话题]# #综艺[话题]# #综艺推荐[话题]# #女性向游戏[话题]# #少女心游戏安利[话题]# #剧情向游戏[话题]# #游戏推荐[话题]# #角色扮演游戏[话题]# #游戏推荐[话题]# #女性向游戏[话题]#', '', 1752309513000, 1754737910000, '2492', '1487', '633', '73', '\"http://sns-web-i10.rednotecdn.com/202606101815/95b20e70d8cb729b92a5793195269a47/1040g2sg31jr4a0p6iujg5nkc87n094dfr5tqvf8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/8a3ae08e4c446af6ed101046df9caae4/1040g2sg31jr4a0p6iuig5nkc87n094dfh47nvg0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/a10325046b8fc15e8b2f331b399d171d/1040g2sg31jr4a0p6iuh05nkc87n094dfqg50vfg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/d69c4297929bfa492ff45b840facde59/1040g2sg31jr4a0p6iui05nkc87n094df4to99l0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/02e6a26e5183e88349c541cf7afdbed5/1040g2sg31jr4a0p6iuhg5nkc87n094dfih98c2g!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/e96cc6b7cb13fbfeccd2b9b3f813f926/1040g2sg31jr4a0p6iuf05nkc87n094df58kiit8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/551fa244fb2a7069c3776b95051bc94b/1