INSERT INTO `xhs_note` VALUES (95, '63a44a300000000026010fbb', '少女の日记', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31sfopjafla0g5ot498o9i3tr2jr9eqo', '', 1781086571132, 1781089189080, '68c961a80000000013009ebc', 'normal', '新发夹太萌了〰️🐰美乐蒂和小羊', '是无痕发夹哦～\n有两个颜色 暖粉色和冷粉色\n	\n#美乐蒂[话题]# #小羊[话题]##必爱诺[话题]##萌物[话题]# #大发夹侧边[话题]# #可爱发夹[话题]# #公主头发卡[话题]# #刘海夹[话题]# #刘海碎发夹[话题]# #碎发夹[话题]# #公主头发卡[话题]# #手工发夹[话题]# #发夹[话题]# #大发夹侧边[话题]# #狗狗发夹[话题]# #宝宝发夹[话题]# #发夹发饰[话题]# #侧边麻花辫发夹[话题]# #发夹推荐[话题]# #发卡[话题]##发夹[话题]##可爱[话题]##手作[话题]# #古早感[话题]# #古早[话题]##甜妹[话题]#', '', 1758028200000, 1758028201000, '1878', '346', '24', '70', '\"http://sns-web-i10.rednotecdn.com/202606101815/a3be8f7b6e0d4c85cebb92a2c3381f1f/notes_pre_post/1040g3k031mgaf93qkq3g5ot498o9i3tr9tln7i0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/3fffa1cddd7a1ae193c8882ecf299e76/notes_pre_post/1040g3k031mgaf93qkq405ot498o9i3tr74q9us8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101815/06c78c3efc4e971640607721b859571a/notes_pre_post/1040g3k031mgaf93qkq4g5ot498o9i3trb8aha30!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7f8e\\u4e50\\u8482,\\u5c0f\\u7f8a,\\u5fc5\\u7231\\u8bfa,\\u840c\\u7269,\\u5927\\u53d1\\u5939\\u4fa7\\u8fb9,\\u53ef\\u7231\\u53d1\\u5939,\\u516c\\u4e3b\\u5934\\u53d1\\u5361,\\u5218\\u6d77\\u5939,\\u5218\\u6d77\\u788e\\u53d1\\u5939,\\u788e\\u53d1\\u5939,\\u624b\\u5de5\\u53d1\\u5939,\\u53d1\\u5939,\\u72d7\\u72d7\\u53d1\\u5939,\\u5b9d\\u5b9d\\u53d1\\u5939,\\u53d1\\u5939\\u53d1\\u9970,\\u4fa7\\u8fb9\\u9ebb\\u82b1\\u8fab\\u53d1\\u5939,\\u53d1\\u5939\\u63a8\\u8350,\\u53d1\\u5361,\\u53ef\\u7231,\\u624b\\u4f5c,\\u53e4\\u65e9\\u611f,\\u53e4\\u65e9,\\u751c\\u59b9\"', 'https://www.xiaohongshu.com/explore/68c961a80000000013009ebc?xsec_token=ABTzBzHP2EmSgVaYKFu5zUsL5PrYpwkBGlaegeVfV7cV8=&xsec_source=pc_search', '雅马哈 YDP165 外接设备', 'ABTzBzHP2EmSgVaYKFu5zUsL5PrYpwkBGlaegeVfV7cV8=');
INSERT INTO `xhs_note` VALUES (96, '606e775a000000000101d757', '🌸', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3170fum60466g5o3eetd0blqntoljjno', '', 1781086571174, 1781089189114, '6746d860000000000703b9a0', 'normal', '想买电钢琴的姐妹，提前参考❗', '‼️关于电钢琴\n1️⃣预算范围\n▪️1000元以内都很差，不建议；\n▪️适合初学者入门进阶使用的（1000～5000左右）\n▪️高性价比的电钢琴（5000～10000元）\n▪️进阶高端款，初学者不建议买，有点没必要啦（10000以上）\n-\n2️⃣ 款式分类\n▪️便携电钢琴，一般体积小重量轻，可以搬运，适合租房/宿舍\n▪️立式电钢琴，只能家用，且体积大重量重，比较占地方\n-\n3️⃣ 品牌推荐\n买电钢琴不要买杂牌琴，认准品牌不会出错。\n▪️日系主流：雅马哈、卡西欧、罗兰、卡瓦依\n▪️崛起国产：美得理\n-\n⚠️注意事项\n1、品牌懂的不多，怕选错，花的钱不值\n2、各档次各型号错综复杂，无从下手，说三道四都不一样\n3、朋友老师推荐，不知道说的专不专业，或是跟风错到底，或者全凭感觉选，心里没底\n4、好不容易看好品牌和型号，不知道什么价格才是最合适的，怕当大冤种，都是血汗钱!\n5、在自己的预算里面能不能尽可能的选到品质最好的那款\n-\n💡个人推荐琴\n✅ 罗兰RP-30X\n采用PHA-4Standard象牙质感键盘和“擒纵机构”，手感很好。音色方面或多或少会有种电子味在里面，同样可以通过外接音箱或耳机来解决，适合注重手感、平时练琴比较多的人。\n-\n✅ 卡西欧AP-S450\nAP-S450是卡西欧高端立式电钢入门款，超薄外观，采样百万级三角钢琴音源，256复音数，拥有木塑混合键盘，手感反馈优秀，日常弹奏或考级练习非常合适。20w+20w功率，双通道四扬声器，音质很赞。\n-\n✅ 雅马哈P525\nP-525在对原有CFX大钢琴采样和头模采样进行了更新，并增强了VRM建模的相关功能。\n在键盘方面，P-525键盘由NWX木塑键盘升级为 GrandTouch-S木塑键床，属于雅马哈高端键床，手感非常好。蓝牙系统新增了MIDI功能，扬声器52W，外放音质非常好。是贵价电钢琴中非常值得的一款。\n-\n✅ 卡西欧PX-S7000\n缃黄色设计既现代又和谐，能融入多样家居环境。革新扬声器系统搭载四个独立驱动扬声器，配合实木复合材质机身，360度传递清澈音质。不论摆放位置如何，内置的钢琴位置功能都能优化声音效果。采用先进的AiR音源技术，真实还原三角钢琴音色，配备智能混合重锤键盘，确保每一次触键都充满表现力。内置蓝牙功能，方便连接外设。\n#电钢琴[话题]# #日常练琴[话题]# #电钢琴选购[话题]# #电钢琴推荐[话题]#  #今天你练琴了吗[话题]#', '', 1732696160000, 1736576933000, '1822', '2064', '285', '403', '\"http://sns-web-i10.rednotecdn.com/202606101815/f44443d4b6205615d8ed39d60effef7e/1040g2sg31cghbinpgkd05o3eetd0blqndua9200!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u65e5\\u5e38\\u7ec3\\u7434,\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u4eca\\u5929\\u4f60\\u7ec3\\u7434\\u4e86\\u5417\"', 'https://www.xiaohongshu.com/explore/6746d860000000000703b9a0?xsec_token=ABoYgrIkvymAzKdDwZu-IU4U42cWENUG4xTvrm44XDlLk=&xsec_source=pc_search', '雅马哈 YDP165 外接设备', 'ABoYgrIkvymAzKdDwZu-IU4U42cWENUG4xTvrm44XDlLk=');
INSERT INTO `xhs_note` VALUES (97, '5bd0ce8238ba630001c86053', 'William', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31b5r5oim6u004bjnjq784o2jfv341no', '', 1781086571210, 1781086571210, '65d75d4c0000000007026e93', 'normal', '奶奶送的新年礼物妈妈都羡慕住了…', '学琴19个月，奶奶二话不说就送了一台雅马哈，五周岁喜提三脚架，接下去要更加努力练琴了哟[抠鼻R]\n	\n#日常碎片PLOG[话题]# #家有琴童[话题]# #新年礼物[话题]# #雅马哈钢琴[话题]# #琴童家长[话题]# #琴童成长[话题]#', '', 1708612940000, 1708612941000, '1591', '377', '114', '106', '\"http://sns-web-i10.rednotecdn.com/202606101815/b989cfbec906b57f88e8c4d7d6c2afde/1040g2sg30vg0c90im2004bjnjq784o2j0pfntt8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u65e5\\u5e38\\u788e\\u7247PLOG,\\u5bb6\\u6709\\u7434\\u7ae5,\\u65b0\\u5e74\\u793c\\u7269,\\u96c5\\u9a6c\\u54c8\\u94a2\\u7434,\\u7434\\u7ae5\\u5bb6\\u957f,\\u7434\\u7ae5\\u6210\\u957f\"', 'https://www.xiaohongshu.com/explore/65d75d4c0000000007026e93?xsec_token=ABG5TGIH4kPwYCqL49bSXucojQxqaYetTUikVQyBIi3y4=&xsec_source=pc_search', '雅马哈 YDP165 外接设备', 'ABG5TGIH4kPwYCqL49bSXucojQxqaYetTUikVQyBIi3y4=');
INSERT INTO `xhs_note` VALUES (98, '5c650e6700000000100355c6', '喜欢语文的刘老师', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31ln6v1p350005n351pjk6le6hor7ot8', '', 1781086571251, 1781089189176, '68c954fb000000001201ebeb', 'video', '🎉今天被推门听课了，领导直夸孩子们乖🥰', '🌟太棒啦！一年级小豆包第三周公开课完美收官！🎉\n听课老师们都夸孩子们配合度满分💯\n一个个坐得端端正正，举手发言超积极👏\n为师欣慰感瞬间爆棚🥹\n记录下这群小豆包的成长瞬间📸\n真的每天都在被孩子们治愈呀💖\n#一年级老师[话题]# #课堂实录[话题]# #公开课[话题]# #教师日常[话题]# #小学生成长记[话题]# #老师的幸福感[话题]# #萌娃上课日常[话题]#', 'http://sns-video-bd.xhscdn.com/pre_post/1040g0cg31mg9jvbskul05n351pjk6le6d8tmqt0', 1758024955000, 1758940162000, '1377', '796', '102', '86', '\"http://sns-web-i10.rednotecdn.com/202606101815/6efda458d0b89383b368d05dbea08ca7/1040g2sg31mg9jvbi4ueg5n351pjk6le6o6e5kno!nd_dft_wlteh_webp_3?src=A\"', '\"\\u4e00\\u5e74\\u7ea7\\u8001\\u5e08,\\u8bfe\\u5802\\u5b9e\\u5f55,\\u516c\\u5f00\\u8bfe,\\u6559\\u5e08\\u65e5\\u5e38,\\u5c0f\\u5b66\\u751f\\u6210\\u957f\\u8bb0,\\u8001\\u5e08\\u7684\\u5e78\\u798f\\u611f,\\u840c\\u5a03\\u4e0a\\u8bfe\\u65e5\\u5e38\"', 'https://www.xiaohongshu.com/explore/68c954fb000000001201ebeb?xsec_token=ABTzBzHP2EmSgVaYKFu5zUsPCXjAsOtq-zvNIJt4ybkYI=&xsec_source=pc_search', '雅马哈 YDP165 外接设备', 'ABTzBzHP2EmSgVaYKFu5zUsPCXjAsOtq-zvNIJt4ybkYI=');
