INSERT INTO `xhs_note` VALUES (102, '6177592700000000020254fa', '波波糖老师的资料库🍬', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31jm058tm2i6g5obnb4jgkl7ql4n22lo', '', 1781087166726, 1781089189393, '68d3628e0000000013006639', 'normal', '一年级上册数学必考10大看图列算式✅', '🔥一年级上册数学的重难点：看图列算式专项训练\n👩🏻👩🏻👩🏻难在题型多变，很多孩子搞不清！其实常见的就是这十大类型！\n⭐⭐⭐有答案，有答案❗❗❗❗\n⭕⭕⭕这种看图列算式的题，不管是期中、还是期末，还是平时单元测试都是要考的！占的分数还挺多！\n✍🏻✍🏻✍🏻平时课后可以打印🖨️出来给孩子练一练，哪种题型不会补哪种！\n🌈🌈🌈每道题都是彩色画图，打印出来更有趣，孩子也不排斥！\n↓↓↓🛒🛒🛒共40页，完整电子版可打印！！\n#一年级上册数学[话题]# #看图列式[话题]# #看图列算式[话题]# #看图列式专项[话题]# #练习题[话题]# #一年级数学上册[话题]# #假期作业[话题]# #看图列算式专项练习[话题]##口诀[话题]#', '', 1758683790000, 1762429281000, '1026', '1092', '15', '180', '\"http://sns-web-i10.rednotecdn.com/202606101825/bc2af6b9c5ec2bc7e359eba38d5e4d2c/1040g2sg31mq3p8p04sd05obnb4jgkl7q0ri7v6o!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/2b8c0780f9a5811c3fbd23ec2d2aa42d/notes_pre_post/1040g3k031mq3p9m74q5g5obnb4jgkl7q5q3gdd8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/10b87d1f3175faf0f8023d457e7391bd/notes_pre_post/1040g3k031mq3p9m74q3g5obnb4jgkl7qo1lksoo!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/3482033f978373512d3dd685ea412bc7/1040g2sg31ohtls6c50bg5obnb4jgkl7q25sqkq0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/f6db506f2526428224ff12dff2059826/notes_pre_post/1040g3k031mq3p9m74q405obnb4jgkl7qhrqp5so!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/3ec6da6b5cf84d45e9f29d6e729ebfd1/1040g2sg31ohtls6c50c05obnb4jgkl7qf506qfo!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/7073a19f27c754a5463872f8b9c7a4e5/notes_pre_post/1040g3k031mq3p9m74q205obnb4jgkl7qaftte50!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/1175e49373138eeb4adeb4ac88e52c7d/1040g2sg31ohtls6c50b05obnb4jgkl7q65bbi60!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/376299cb82c27cb66bc7d8551569290f/1040g2sg31ohtls6c50805obnb4jgkl7qvvvn6o8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/d6cda07aa71f60020b8423f3852d9f01/1040g2sg31ohtls6c508g5obnb4jgkl7q7seapkg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/5ddf39633f10b7ad1e14a3c6455ad257/notes_pre_post/1040g3k031mq3p9m74q2g5obnb4jgkl7q1r04cd8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u4e00\\u5e74\\u7ea7\\u4e0a\\u518c\\u6570\\u5b66,\\u770b\\u56fe\\u5217\\u5f0f,\\u770b\\u56fe\\u5217\\u7b97\\u5f0f,\\u770b\\u56fe\\u5217\\u5f0f\\u4e13\\u9879,\\u7ec3\\u4e60\\u9898,\\u4e00\\u5e74\\u7ea7\\u6570\\u5b66\\u4e0a\\u518c,\\u5047\\u671f\\u4f5c\\u4e1a,\\u770b\\u56fe\\u5217\\u7b97\\u5f0f\\u4e13\\u9879\\u7ec3\\u4e60,\\u53e3\\u8bc0\"', 'https://www.xiaohongshu.com/explore/68d3628e0000000013006639?xsec_token=ABGoiu3sayJyfG08QtJAOdQXjIMAKyQwQSjf9jvSCmePw=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'ABGoiu3sayJyfG08QtJAOdQXjIMAKyQwQSjf9jvSCmePw=');
INSERT INTO `xhs_note` VALUES (103, '676635b80000000018014288', 'Kitty满脑子只有游戏', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3213vddo4na6g5pr66ms62gk8g0hgt48', '', 1781087166763, 1781089189520, '688dc2360000000005006c9d', 'normal', '蜡笔小新煤炭镇的小白手机平板都可以玩咯', '家人们谁懂啊，生活里总有这些闹心时刻：被同事的一句闲话搞得心烦意乱，为早上选错衣服纠结一整天，想起曾经错过的机会就懊恼不已……每天都被这些情绪内耗，真的好累！\n直到我玩了《蜡笔小新煤炭镇的小白》，仿佛打开新世界大门！在游戏里，我操控小新和小白，在充满昭和风情的煤炭镇开启欢乐冒险。这里没有KPI，没有催婚，只有最纯粹的快乐。\n游戏里有超多有趣玩法，钓鱼、捉虫、种菜，每项都能让我沉浸其中，不再为生活里的琐碎小事瞎操心，完美诠释“停止过度思考，珍惜当下美好” 。当我专注于和小新一起寻找昆虫，或者等待鱼儿上钩时，那些日常的焦虑瞬间烟消云散，只享受当下的宁静与快乐。\n而且在煤炭镇，完全不用在意别人的眼光。小新还是那个爱搞怪、跳屁屁舞的小孩，不在意他人评价，尽情做自己 。游戏里的居民也都超级友好包容，让我深刻体会到，生活是自己的，不必活在他人的期待里。\n游戏中还有一条重要的故事线：小新一家来到秋田乡村，一开始对陌生环境诸多不适应，但慢慢地，他们接受并爱上这里，开启新生活。这不就是“接受过去，勇敢向前” 嘛！过去的遗憾无法改变，但可以成为成长的养分。就像我们不能改变曾经的错误决定，却能从中吸取教训，过好当下。\n另外，游戏里不同场景都有独特的美。小镇的街道、宁静的田野、神秘的矿山 ，每次探索新地方都有新惊喜，让我不再羡慕别人的生活，珍惜自己拥有的一切。\n在这个游戏世界里，我感受到简单纯粹的快乐，领悟到保持好心态的重要性 。不管现实生活多糟糕，只要心态积极，总能发现美好。\n真心推荐给被生活压得喘不过气、急需放松的友友们！来煤炭镇，和小新、小白一起，把烦恼抛到九霄云外 ，拥抱快乐吧~\n#蜡笔小新煤炭镇的小白[话题]# #治愈系游戏[话题]# #释放压力[话题]# #生活感悟[话题]# #宝藏游戏推荐[话题]##ios游戏[话题]##蜡笔小新煤炭镇的小白手机版[话题]# #蜡笔小新煤炭镇的小白下载教程[话题]# #蜡笔小新之煤炭镇的小白中文版[话题]##热门游戏推荐[话题]##ios游戏[话题]# #蜡笔小新煤炭镇[话题]# #蜡笔小新煤炭镇小白[话题]##蜡笔小新煤炭镇的小白下载[话题]# #蜡笔小新煤炭镇小白[话题]# #蜡笔小新煤炭镇的小白教程[话题]##平板游戏[话题]# #蜡笔小新煤炭镇的小白[话题]# #蜡笔小新煤炭镇的小白下载[话题]#', '', 1754120758000, 1754120758000, '887', '261', '26', '98', '\"http://sns-web-i10.rednotecdn.com/202606101825/45ea1fbd764dc7c3daa8435ce92cae8d/1040g00831km3r8mg2u005pr66ms62gk82cs5hq8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/2ad87cb3c59e1231020d14e28e783a6b/1040g00831km3r8mg2u0g5pr66ms62gk8t8ksrng!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/2e1c66a2013937f85b46b09dfaef31a4/1040g00831km3r8mg2u105pr66ms62gk89sq07qg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/0993c59a9f8790391d879585f1ecce75/1040g00831km3r8mg2u1g5pr66ms62gk883qi3no!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/0dec9b195a4924fb3ecc02ea20ee9d2a/1040g00831km3r8mg