INSERT INTO `xhs_note` VALUES (105, '671b8b0c000000001d0235f4', '小西幼教吖', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31f9msd2fmo6g5porhc67cdfkiqtbs0o', '', 1781087166832, 1781088298708, '68ef2c0f000000000301955b', 'normal', '幼儿园故事创编盒子语言区区域投放素材', '幼儿园语言区创编故事盒子区域投放素材，可打印\n根据图上内容，让孩子们创编故事！\n孩子们玩嗨了[赞R]\n	\n#幼儿园语言区[话题]# #小西幼教[话题]# #故事盒子[话题]# #故事盒子自制[话题]# #故事盒子素材[话题]# #幼儿园阅读区故事盒子[话题]# #幼儿园语言区故事盒子[话题]# #创编故事[话题]# #创编故事盒子[话题]# #创编故事可打印[话题]# #语言区[话题]# #语言区素材[话题]# #语言区教具[话题]# #语言区材料[话题]# #语言区故事盒子[话题]# #语言区材料投放[话题]# #大班自制玩教具语言区[话题]# #大班语言区素材[话题]# #中班语言区素材[话题]# #幼儿园故事创编[话题]# #故事创编[话题]# #自制玩教具幼儿园[话题]# #创编故事盒子[话题]#', '', 1760504847000, 1760669002000, '734', '479', '1', '120', '\"http://sns-web-i10.rednotecdn.com/202606101825/db8ced8e895bc40cfcbac626efc02ba3/1040g00831nnmivn4g6605porhc67cdfk0pqcm4o!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/f040a3ac64a06b6408ac1c8a57dcaa2d/1040g00831nnmivn4g64g5porhc67cdfkag5lkug!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/6cf3b60c174d6a1fe5234d5ce3c98f10/1040g00831nnmivn4g63g5porhc67cdfkto0r7ro!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/a5b328519816078c575d0ba153dc6c7d/1040g00831nnmivn4g6405porhc67cdfkhl0jvo8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u5e7c\\u513f\\u56ed\\u8bed\\u8a00\\u533a,\\u5c0f\\u897f\\u5e7c\\u6559,\\u6545\\u4e8b\\u76d2\\u5b50,\\u6545\\u4e8b\\u76d2\\u5b50\\u81ea\\u5236,\\u6545\\u4e8b\\u76d2\\u5b50\\u7d20\\u6750,\\u5e7c\\u513f\\u56ed\\u9605\\u8bfb\\u533a\\u6545\\u4e8b\\u76d2\\u5b50,\\u5e7c\\u513f\\u56ed\\u8bed\\u8a00\\u533a\\u6545\\u4e8b\\u76d2\\u5b50,\\u521b\\u7f16\\u6545\\u4e8b,\\u521b\\u7f16\\u6545\\u4e8b\\u76d2\\u5b50,\\u521b\\u7f16\\u6545\\u4e8b\\u53ef\\u6253\\u5370,\\u8bed\\u8a00\\u533a,\\u8bed\\u8a00\\u533a\\u7d20\\u6750,\\u8bed\\u8a00\\u533a\\u6559\\u5177,\\u8bed\\u8a00\\u533a\\u6750\\u6599,\\u8bed\\u8a00\\u533a\\u6545\\u4e8b\\u76d2\\u5b50,\\u8bed\\u8a00\\u533a\\u6750\\u6599\\u6295\\u653e,\\u5927\\u73ed\\u81ea\\u5236\\u73a9\\u6559\\u