INSERT INTO `xhs_note` VALUES (106, '5b3c9c074eacab6d624477fb', '黛山尺水', 'https://sns-avatar-qc.xhscdn.com/avatar/1ac11ee2-d273-3b5a-841d-df3e42930b0b', '', 1781087166861, 1781087166861, '690ca2c50000000005031431', 'video', '‼️师父说：相由心生/女人带不带财，就看脸', '#大连外国语大学的银杏伞好浪漫[话题]#\n‼️师傅说：\n相由心生/女人带不带财，就看脸\n女人的‘相’与‘财’实则是\n同频能量的双生花。\n#寺庙旅行[话题]# #缘起缘灭自有定数[话题]# #相由心生[话题]##佛说生活本就是一场修行[话题]# #灵魂伴侣可遇不可求[话题]# #上班上进上香[话题]# #线香玄学[话题]# #线香推荐[话题]# #境随心转相由心生[话题]#', 'http://sns-video-bd.xhscdn.com/pre_post/1040g2t031oi0or4bmml04a6r2ce0etvri83c1m8', 1762435781000, 1763607105000, '696', '203', '75', '46', '\"http://sns-web-i10.rednotecdn.com/202606101825/1bf7821fdc54a9564252d3ff0fa4cccb/1040g00831oi0or4dlm004a6r2ce0etvro1km1rg!nd_dft_wlteh_webp_3?src=A\"', '\"\\u5927\\u8fde\\u5916\\u56fd\\u8bed\\u5927\\u5b66\\u7684\\u94f6\\u674f\\u4f1e\\u597d\\u6d6a\\u6f2b,\\u5bfa\\u5e99\\u65c5\\u884c,\\u7f18\\u8d77\\u7f18\\u706d\\u81ea\\u6709\\u5b9a\\u6570,\\u76f8\\u7531\\u5fc3\\u751f,\\u4f5b\\u8bf4\\u751f\\u6d3b\\u672c\\u5c31\\u662f\\u4e00\\u573a\\u4fee\\u884c,\\u7075\\u9b42\\u4f34\\u4fa3\\u53ef\\u9047\\u4e0d\\u53ef\\u6c42,\\u4e0a\\u73ed\\u4e0a\\u8fdb\\u4e0a\\u9999,\\u7ebf\\u9999\\u7384\\u5b66,\\u7ebf\\u9999\\u63a8\\u8350,\\u5883\\u968f\\u5fc3\\u8f6c\\u76f8\\u7531\\u5fc3\\u751f\"', 'https://www.xiaohongshu.com/explore/690ca2c50000000005031431?xsec_token=ABo06ZiRJvEfM9VFIL5iOVqUwFSaKdRd0Mcov2nh_xjF4=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'ABo06ZiRJvEfM9VFIL5iOVqUwFSaKdRd0Mcov2nh_xjF4=');
INSERT INTO `xhs_note` VALUES (107, '66c4251c000000001d020b10', '橙子🍊的学琴笔记', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31qtbhltlgm605pm44ke7c2oggnd2fjg', '', 1781087166889, 1781087166889, '66f9148c000000001b02378e', 'normal', '不懂电钢琴怎么选的看过来', '💡分享行内人才知道的一些小tips\n1、价格不是判断电钢琴好坏的唯☝️标准，要选择符合自己预算和学习需求的琴。\n2、预算1000以下的话，攒攒钱再买吧，1000以下没什么好琴。\n3、初学阶段新手对音色、手感还不太敏感，选主流品牌的电钢不会出错。\n4、新手不建议去某鱼市场买琴，二手水太深。\n	\n💡分享一些口碑不错的新手电钢琴\n【1-2k】卡西欧CDP-S110、卡西欧EP-S130、罗兰FP-18、美得理SP-C120、雅马哈P48、艾茉森P60\n【2-3k】艾茉森V03、卡瓦依ES120、卡瓦依ES110、雅马哈P125、卡瓦依KDP110\n【3-4k】卡西欧PX-S1100、雅马哈P225、罗兰FP-30X\n【4-5k】卡西欧PX-870、罗兰RP107、卡瓦依KDP120、 KORG sp280、雅马哈YDP105\n【5-6k】罗兰F701、雅马哈YDP145\n【6-10k】卡瓦依CN201、雅马哈YDP165、卡西欧AP-S450\n——\n#线上钢琴教学[话题]# #钢琴老师[话题]# #零基础学钢琴[话题]# #电钢琴[话题]# #电钢琴选购[话题]# #成人钢琴[话题]#', '', 1727599756000, 1730171346000, '639', '697', '214', '95', '\"http://sns-web-i10.rednotecdn.com/202606101825/1977bd6bf4d4413cfbd0d1f4b18c011f/1040g2sg319h87e2r6qcg5pm44ke7c2og3ntfdng!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7ebf\\u4e0a\\u94a2\\u7434\\u6559\\u5b66,\\u94a2\\u7434\\u8001\\u5e08,\\u96f6\\u57fa\\u7840\\u5b66\\u94a2\\u7434,\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u6210\\u4eba\\u94a2\\u7434\"', 'https://www.xiaohongshu.com/explore/66f9148c000000001b02378e?xsec_token=AB4yrakYib0o50bjDZATGIucE-3AYN_yFayvSiSlN8Glw=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'AB4yrakYib0o50bjDZATGIucE-3AYN_yFayvSiSlN8Glw=');
INSERT INTO `xhs_note` VALUES (108, '5b0c1b6d11be103379094ef8', '迪迪', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3179ep2qpju5g4a5nundmqjnod2uptmo', '', 1781087166915, 1781087166915, '67a9bce80000000018012ed4', 'normal', '电钢琴购买心得和建议', '一、先放结论：\n经过我这段时间做的功课，推荐如下：\n	\n1、卡西欧CDP-S110：价格亲民，只要一千五左右，复音数64，音色数10，对于预算低的新手来说是性价比非常高的一款。\n2、雅马哈P125或225：雅马哈的热销机型，125在2800左右，225在3500左右，225无论是在音源还是键盘上都比125高了一个档次。\n3、卡西欧PX870：四千左右的价格，复音数256，音色19，四个10瓦扬声器，重点是还是一款立式琴。复音数足够高，弹复杂的曲子不会丢音，可以直接考10级，比起普通琴多了两个扬声器，外放音质更赞了，另外还是自带滑盖的，不会落灰。这款重点推荐。\n4、卡瓦依KDP120：比PX870贵一点，五千二左右，同样是256复音数，20瓦扬声器，如果预算充足，这款不错的选择。\n	\n当然，如果预算在七八千左右的，雅马哈P515、卡瓦依CA33这些高端型号也可以考虑，手感和音色都更上一层楼！\n	\nTips：蹲活动价，可以重点关注双11 双12 618这些时间节点，一般是价格醉优惠的时候了，平时价格会有变动，也是建议放在购物车常点进去看看价格有没有变低。\n	\n二、国产电钢琴推荐吗？\n先说结论：不是太推荐。我自己去店里体验过现在网上大火的几款型号，总体感觉真的不如现在主流的四个大牌子。\n目前国产技术不成熟，同样的价格买一台国产的电钢琴类为什么不买国际认证的大牌呢？更何况现在还有太多打广告的杂牌子混入其中，真的防不胜防。\n	\n三、钢琴还是电钢琴？\n1、1w以下，不建议买钢琴。实在想要那就只能海鲜市场，淘一个靠谱的这种一线大牌的二手吧，不过不懂行的人大概率会被骗。\n2、如果是1w以下的预算，在自己家里想自由练琴，我还是建议买个电钢琴，现在电钢琴性价比都很高，还能戴耳机静音练琴，真的是醉适合业余玩家的选择了。\n#电钢琴[话题]# #零基础学钢琴[话题]# #电钢琴选购[话题]# #钢琴教育[话题]# #钢琴[话题]# #钢琴教学[话题]#', '', 1739177192000, 1739177193000, '543', '475', '17', '56', '\"http://sns-web-i10.rednotecdn.com/202606101825/7da6eddf3b9bf2fc05488317e76abfe6/1040g2sg31dneho77gs6g4a5nundmqjnoqm7d2n0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/97b95f15c235153cabd8a491dd87568b/1040g2sg31dneho7n0m6g4a5nundmqjnout1gfk8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u96f6\\u57fa\\u7840\\u5b66\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u94a2\\u7434\\u6559\\u80b2,\\u94a2\\u7434,\\u94a2\\u7434\\u6559\\u5b66\"', 'https://www.xiaohongshu.com/explore/67a9bce80000000018012ed4?xsec_token=ABRiqANNpYklqQSAu8srnNMxXeodFhW5-jhaCBBdNszX0=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'ABRiqANNpYklqQSAu8srnNMxXeodFhW5-jhaCBBdNszX0=');
INSERT INTO `xhs_note` VALUES (109, '55c3cb1ef5a26322b8b74126', '诺拉拉拉呀', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30tjkiii2ku0g411n7h5hsg96mbafvd0', '', 1781087166948, 1781087166948, '68cea34e000000001201f0b9', 'normal', '在闲鱼800自提了一台二手雅马哈电钢', '最近报了社区学校的电子钢琴课，80块钱十二节，感觉还挺有趣的，老师说我们可以回家自己多练练。可是家里没有琴，而且我知道自己也是三分钟热度的人，所以淘一台二手电钢琴对我来说比较有性价比的选择。\n	\n因为是小白，完全不懂钢琴各个牌子的门道，所以先在小红书简单做了一下功课，看看适合新手入门的都有哪些牌子，然后再根据品牌和自己能接受的价格再在闲鱼上搜索。选购的时候遇到了一个比较大的难点：这类电钢琴体积比较大，所以很多个人闲置卖家不愿意邮寄，或需要运费到付，大部分都是要求自提的。自提的话就会比较限制和物品距离。\n	\n于是我尝试按照距离搜索家附近15km的地方，刚好看到有一位用户在出雅马哈的电钢琴，报价960元，九新，大概是全新价格的五折。浏览了页面，没有显示信用，但挂着的商品都是女生的包包，玩偶，背景生活化，根据经验我判断是一位20-30岁左右的女孩。\n	\n买二手，总归还是要砍砍价的。我私聊了卖家，询问自提是否可以便宜一些。本来我想着，能讲到900块我就已经可以入手了，结果卖家直接回复最低800。我大喜过望，比我预想的还要低了100块，还是很有诚意的，再讲价我就有些贪心了，于是很愉快地约定了自提的时间和地点，我在货拉拉小程序上预定了一个小型的面包车并加钱购买了搬运服务（因为我家是步梯五楼），从下单到拿到电钢琴到把物品妥善放置在家里的阳台，全程只花了不到三个小时。\n	\n好玩的是，出钢琴的女孩是学习学前教育的，因为学业需要，购买了钢琴，但实际上只用过几次，就一直在家里吃灰，因为最近整理物品才想到要把钢琴出掉，也很巧遇到我这个刚学钢琴的三分钟热度的小白，一拍即合，顺利完成这次自提交易。\n	\n小的时候家里条件不是很好，觉得购买钢琴学习钢琴都是很奢侈的事情，但心里其实对钢琴是存在一种隐秘的向往和羡慕的。现在长大了，可以自己独立工作生活，才发现很多东西并不是那么遥不可及，80块就可以上一个学期的钢琴课，800块就可以买到一架成色很好的大品牌的入门级电钢琴，更不要说网上浩如烟海的免费学习资源，只需要你有时间精力和兴趣去慢慢地探索和发现。\n	\n我想说，虽然是二手物品，但反而可以让物品从不需要的人手里流通到需要的人的手里，而且能自己赚钱买自己喜欢的大玩具真是超级超级幸福的一件事情呀[萌萌哒R]', '', 1758372686000, 1758372686000, '535', '216', '172', '48', '\"http://sns-web-i10.rednotecdn.com/202606101825/906752e1b18ef8acdd4df3e76b4ccf94/notes_pre_post/1040g3k831mlejtr5l250411n7h5hsg96c2itkmo!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/8b9e562be7df08e73303252aeb2159c2/notes_pre_post/1040g3k831mlejtr5l25g411n7h5hsg966f0975o!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/f7a26c143619c4daa3e604eaafe12351/notes_pre_post/1040g3k831mlejtr5l240411n7h5hsg96cfk05o8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/495785fb50bbdede76490feaca854e81/notes_pre_post/1040g3k831mlejtr5l24g411n7h5hsg969ecj5ig!nd_dft_wlteh_webp_3?src=A\"', '\"\"', 'https://www.xiaohongshu.com/explore/68cea34e000000001201f0b9?xsec_token=ABacnXaJzHTcYY-hcT-BR5SPq38J2hu1f0QWtvU8pRLuI=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'ABacnXaJzHTcYY-hcT-BR5SPq38J2hu1f0QWtvU8pRLuI=');
INSERT INTO `xhs_note` VALUES (110, '62d771ce0000000002001fb7', '睿叔', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30vqdsa9dlu005omne770g7tnkkpffu8', '', 1781087166982, 1781087166982, '66ff7776000000002c0285bf', 'normal', 'YAMAHA真的是无敌……😘', '接上一篇说，“我建议你们去看Nissan总部周围的公司”因为还有雅马哈、FUJIfilm、SONY占据童年的企业\n尤其是YAMAHA（毕竟人生第一台电子琴）就是从这起步的……\n所以乐器类占据2层楼，钢琴、小号、吉他……啥都有，并且都可以亲自感受一下，甚至现场创作。工作人员巴不得你来体验。（一楼的顶级钢琴区也有，我没那个实力就不去了）音乐爱好者不容错过！\n由于YAMAHA涉及领域众多，而且只要它涉及的都还挺牛逼，所以心想摩托必须好好看一下。可没想到这个电动助力车成了亮点，尤其是这个pas city-c，小巧又方便，还骑去横滨港周围感受了一下，瞬间种草🌿，虽然是最便宜的一类，但也要145200円（合7200rmb）\n顺便再提一嘴：“这个办公环境，着实又慕了”\n有想去YAMAHA上班的冲动[折叠椅R]#日本[话题]# #横滨[话题]# #雅马哈[话题]# #YAMAHA[话题]# #钢琴[话题]# #海外生活[话题]#', '', 1728018294000, 1728020321000, '512', '233', '26', '123', '\"http://sns-web-i10.rednotecdn.com/202606101825/005215f8838e61ae45094ce193c72437/1040g008318h5i8o3jq0g5omne770g7tnf8ba8l0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/2c58f176e523c44ac08a84fa8229f390/1040g008318h5i8o3jq005omne770g7tn87qrri0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/735eb26b3ea5e18c5b13030931e5d770/1040g008318h5i8o3jq105omne770g7tnn5m0pfo!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/d32ca4c1c40167f6a6dd7c051fe9fa3a/1040g008318h5i8o3jq1g5omne770g7tnhfnn4m0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/880445fd5ae912d9ea24ae20ad9fdd40/1040g008318h5i8o3jq205omne770g7tn7pf3ejg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/9fed1e974a53e8d761741585cac9e803/1040g008318h5i8o3jq2g5omne770g7tnfj881h8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/4219361525b915539d6beb10b03e7c3c/1040g008318h5i8o3jq305omne770g7tncr1fim0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/6684ae5ed39a0afbca5df911c60c142b/1040g008318h5i8o3jq3g5omne770g7tnkk4gino!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/e9ccadd97cb8a5c12e3a5f2214677eb8/1040g008318h5i8o3jq405omne770g7tnduebg10!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/b6e2c18cb18325d225513d24cf9891f4/1040g008318h5i8o3jq4g5omne770g7tntvoe748!nd_dft_wlteh_webp_3?src=A\"', '\"\\u65e5\\u672c,\\u6a2a\\u6ee8,\\u96c5\\u9a6c\\u54c8,YAMAHA,\\u94a2\\u7434,\\u6d77\\u5916\\u751f\\u6d3b\"', 'https://www.xiaohongshu.com/explore/66ff7776000000002c0285bf?xsec_token=ABjmg0JlY0o7PBn9a7F73uIzWOvVnhEIJLLYEVHQPyrJk=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'ABjmg0JlY0o7PBn9a7F73uIzWOvVnhEIJLLYEVHQPyrJk=');
INSERT INTO `xhs_note` VALUES (111, '617fbc49000000001000baea', '闪电摇滚供给站', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30vgv75tm5o605obvnh4k1enad4b3t88', '', 1781087167016, 1781087167016, '691424a800000000050317cd', 'normal', '最后一只现货会发光的fender哥斯拉🌟', 'FENDER*哥斯拉70周年纪念款start日芬fender东京旗舰店芬达最新联动款(上海全新现货!可自提)\n(现货!)#Fender[话题]# /芬德 Fender x哥斯拉70周年国内最后一只到货!!!需要的朋友们已经可以联系我直接买现货了无需预定，Made in Japan Godzilla Stratocaster® Blue蓝色款，絮状枫木贴面，国内首到!实物图放链接里了，按下失真按钮后，根据失真强弱，哥斯拉发光强弱也会跟着变，发出蓝光。实物实拍，包括序列号，可验真伪，上海发货可自提，贵重物品默认顺丰到付保价邮费，全新正品售出不退不换!日本限量发行就这么一批，哥斯拉的版权有限，已经开始涨价，明年铁定站上3w大关，很多小伙伴都在咨询，尽早拿货哦\n辅助搜索：全新吉他 电吉他 贝斯 电贝司 Gibson Fender PRS custom shop CS LTD master mb private stock ibanez esp gretsch jackson murphy lab R6 R7 R8 R9 R0 strat tele martin taylor D18 D28 D41 D42 D45 Om28 OM42 00042 hummingbird dove J45 SJ200 Dale Wilson John Cruz Jason Smith Todd Krause John English Greg Fesler Dannis Galuzuka Levi perry Kyle Mcmillin L5 L4 es335 es175 les paul schecter boss John Mayer JP Musicman Xotic crimson LP JC JS DW VVT Jcustom 墨玩 美专 美源 美豪 美复 strymon T\'s 做旧 吉他 电吉他 木吉他 箱琴 黑卡 aged relic tom Dunlop 拨片 琴弦 elixir m2m strandberg 巴枚 巴西玫瑰木 Epiphone James Tyler Don Grosh Suhr Tom Anderson studio angel SG AZ PIA Yamaha#电吉他推荐[话题]# #fender芬达[话题]# #Fender东京旗舰店[话题]# #fender吉他[话题]# #哥斯拉[话题]# #哥斯拉70周年[话题]# #gozilla[话题]# #哥斯拉手办[话题]# #芬达吉他[话题]#', '', 1762927784000, 1763432622000, '502', '39', '9', '46', '\"http://sns-web-i10.rednotecdn.com/202606101825/1dc678ac1822e6a65da21a06112213d1/note_pre_post_uhdr/1040g3r831opbkooc6md05obvnh4k1enaj3fqva0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/534aa4ac999cb72fd3fabdbdd82b48fe/note_pre_post_uhdr/1040g3r831opbkooc6m8g5obvnh4k1enad2e5578!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/97caec9913ff267e13095b7aabfa74da/notes_pre_post/1040g3k031opbkpf46m5g5obvnh4k1enaibg8tug!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/7e4ac15d6ad2d1df39b81da341f1b863/notes_pre_post/1040g3k031opbkpf46m4g5obvnh4k1enanfndum8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/c954cee258634b8d3640f8b504543f03/notes_pre_post/1040g3k031opbkpf46m305obvnh4k1enaondfmi0!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/7a0bfb181d96d6d2757591a61b42a317/note_pre_post_uhdr/1040g3r831opbkooc6mdg5obvnh4k1enanj8uro0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/89774ee8a64ca4d436b3faab8d7f1ad1/notes_pre_post/1040g3k031opbkpf46m0g5obvnh4k1enacadvnbg!nd_dft_wlteh_webp_3?src=A\"', '\"Fender,\\u7535\\u5409\\u4ed6\\u63a8\\u8350,fender\\u82ac\\u8fbe,Fender\\u4e1c\\u4eac\\u65d7\\u8230\\u5e97,fender\\u5409\\u4ed6,\\u54e5\\u65af\\u62c9,\\u54e5\\u65af\\u62c970\\u5468\\u5e74,gozilla,\\u54e5\\u65af\\u62c9\\u624b\\u529e,\\u82ac\\u8fbe\\u5409\\u4ed6\"', 'https://www.xiaohongshu.com/explore/691424a800000000050317cd?xsec_token=ABOqxW_xKzyf8EkKQonWJJaC3OGZPwjFGjWZRCUxcmSDk=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'ABOqxW_xKzyf8EkKQonWJJaC3OGZPwjFGjWZRCUxcmSDk=');
INSERT INTO `xhs_note` VALUES (112, '58aff7fd6a6a69568dc9bf62', 'Helloaowuu', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31s1lga6lkc10496rq5rvrfr2mi1in00', '', 1781087167047, 1781087167047, '67a4d768000000001800a88c', 'normal', 'YAMAHA三角钢琴开箱｜24岁生日礼物', '电子存档一下Yamaha三角钢琴的开箱🎵\n	\n🎹学琴之路：\n幼儿园开始学电子琴，小学开始学钢琴，五年级考了八级，六年级实在学不下去了，停学一年，初一某一天突然又在爱上琴声就重新继续学，初二就考完十级。\n并不是走专业路线，只是一个普通孩子的童年，但是也想为自己坚持这么久的爱好点个赞！\n考完十级也还有继续学，直到高中的某一天就停止了。连钢琴都没再碰，兴趣也几乎没了。\n大学偶然看到有钢琴的up主，于是自己也尝试着录视频，没想到越录兴致越浓，又回到想天天弹琴的日子。\n后来看到别人用三角钢琴录视频，可以通过琴架映出手指的倒影，觉得太美了！超羡慕！于是爸妈送给了24岁的我，作为生日礼物。到后来工作繁忙，生活劳累，现在又慢慢丢下了钢琴（我就是这样，间歇性兴致勃勃，天天弹，又偶尔一段时间完全不想碰）\n直到今天翻看相册，看到了当年第一次拥有自己的三角钢琴的那种兴奋，莫名很感动。于是记录一下，希望自己永远记得当时的热情，坚持这个陪伴自己童年的兴趣爱好吧！\n	\n💗选购过程：当时预算是8w左右，于是试了市面上几乎所有品牌，有些是去专卖店试，有些是通过卖琴的老板告诉哪个琴行买了某个型号的钢琴，我就去他店里试弹。最后在kawai GL10和yamaha GN1中纠结，最终还是更喜欢雅马哈的音色，于是定下啦！\n	\n💗试弹tips：\n1、备几首可以几乎弹完所有琴键的曲子，我当时是《少女的祈祷》和《平湖秋月》部分片段，不用整首弹，来感受琴键的感觉\n2、备几首自己喜欢的歌曲风格，来感受音色是否是自己喜欢的，是否匹配\n3、可以录下来回家多听几次，仔细感受\n	\n型号：Yamaha GN1（音色在我主页下一篇笔记📒）\n日常录音设备：zoom H1n\n	\n#Yamaha钢琴[话题]# #三角钢琴[话题]# #三角钢琴推荐[话题]# #钢琴选购[话题]#  #雅马哈三角钢琴[话题]# #zoom录音笔[话题]# #雅马哈钢琴[话题]##钢琴购买[话题]#\n	\nbtw准备今年重新装修客厅，到时钢琴就不放在这啦，也当记录一下现在的样子吧～[耶R][耶R]', '', 1738856296000, 1745856788000, '472', '206', '67', '72', '\"http://sns-web-i10.rednotecdn.com/202606101825/eedb4a9ef236c946086a77e98a3b7829/1040g00831dilh6itgu00496rq5rvrfr2c6hdlg0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/a097802e941d2184f1f4606c299bd5c2/1040g00831dilh6itgu0g496rq5rvrfr21uh4h4o!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/cc14d7a3e9e130d7f57ea88fe78abd6d/1040g00831dilh6itgu10496rq5rvrfr28sve6l0!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/36d8169cf1b59c66c3cbe7ca184f1481/1040g00831dilh6itgu1g496rq5rvrfr2gtc55v8!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/29fc1bc2297d316d16d7dbb00a9b5292/1040g00831dilh6itgu20496rq5rvrfr237vo0s8!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/74690a80