INSERT INTO `xhs_note` VALUES (113, '68d77f9b000000002101eb64', '安安的学习分享', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31n592q4e6g005q6nfudobqr47196s1o', '', 1781087167082, 1781087167082, '68de35ac00000000030231ed', 'normal', '钢琴行情这么差了吗⁉️', '三年前一万五买的钢琴现在卖二手说500块钱，咋办?[失望R]\n	\n问了好几家都这么低，有一家还说 300\n钢琴行情这么差了吗?[哭惹R]\n#钢琴[话题]##钢琴回收[话题]##学琴[话题]# #琴童家长[话题]# #练琴[话题]# #弹琴[话题]# #学琴之路[话题]# #电子琴[话题]# #钢琴教学[话题]# #我的生活碎片[话题]#', '', 1759393196000, 1760313947000, '451', '185', '1103', '380', '\"http://sns-web-i10.rednotecdn.com/202606101825/2449de98a7caad7b25d2ecb1aeca93d6/notes_pre_post/1040g3k831n4m3pmvmg705q6nfudobqr4ivo96ng!nd_dft_wlteh_webp_3?src=A\"', '\"\\u94a2\\u7434,\\u94a2\\u7434\\u56de\\u6536,\\u5b66\\u7434,\\u7434\\u7ae5\\u5bb6\\u957f,\\u7ec3\\u7434,\\u5f39\\u7434,\\u5b66\\u7434\\u4e4b\\u8def,\\u7535\\u5b50\\u7434,\\u94a2\\u7434\\u6559\\u5b66,\\u6211\\u7684\\u751f\\u6d3b\\u788e\\u7247\"', 'https://www.xiaohongshu.com/explore/68de35ac00000000030231ed?xsec_token=ABFQ8X-pUVtyjLxDg3JpIi5bBkUxy8gnJjIVqMExFU4yY=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'ABFQ8X-pUVtyjLxDg3JpIi5bBkUxy8gnJjIVqMExFU4yY=');
INSERT INTO `xhs_note` VALUES (114, '5cd99611000000001601af28', '一十一', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31n0bdv6fmm005n6pio8ljbp8sqj1ef0', '', 1781087167114, 1781087167114, '676bdcff000000000900c87a', 'normal', '🇩🇪收到圣诞礼物太快乐啦🤪🤪', '来德国以后一直想买个电钢琴，毕竟从小学了那么多年不想就浪费了，之前看到donner的木纹电钢就深深爱上了非常古典表面一个按键都没有，没想到男盆友记下来型号在圣诞节给我这么大一个惊喜，太开心啦～', '', 1735122175000, 1735122176000, '403', '178', '34', '69', '\"http://sns-web-i10.rednotecdn.com/202606101825/712d8a006fd558faeb1eb5fb59e3e822/1040g00831br0urqggk005n6pio8ljbp8rnqgdfg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/e712f26f1cf73bc808b52388dfc0e500/1040g00831br0urqggk0g5n6pio8ljbp8bou6nlg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/2e1351905d541f0487f568a793161d71/1040g00831br0urqggk105n6pio8ljbp8fe3c7ro!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/db17a16f5e784dc0869814789973e1c5/1040g00831br0urqggk1g5n6pio8ljbp8p9lndoo!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/d582a2b927d3800203e8d0c103f11d9e/1040g00831br0urqggk205n6pio8ljbp8alo2et8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/e3b490e5546bfae431c0090bff63e77a/1040g00831br0urqggk2g5n6pio8ljbp8589bmo8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/a3f02d13b67c0473320eced6e23d72c3/1040g00831br0urqggk305n6pio8ljbp8rgjvgu8!nd_dft_wgth_webp_3?src=A\"', '\"\"', 'https://www.xiaohongshu.com/explore/676bdcff000000000900c87a?xsec_token=AByo1V0XPoifDPhD5Y5nV6tjZhAHm7-_AOrO_cUJ5x-NA=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'AByo1V0XPoifDPhD5Y5nV6tjZhAHm7-_AOrO_cUJ5x-NA=');
