INSERT INTO `xhs_note` VALUES (118, '5cbb1476000000001601a0c2', '南瓜派吖', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31eneht5l5s005n5r2hr5j86239p56g0', '', 1781087167231, 1781087167231, '65ddcc2a000000000702699b', 'normal', '买完就后悔了……', '入手已经快一个月了，现在就是后悔买晚了，有时间和兴趣能练练琴，简直是一件性价比超高的事情了！#电钢琴[话题]# #电钢琴选购[话题]# #钢琴调律[话题]# #雅马哈[话题]# #雅马哈钢琴[话题]# #自学钢琴[话题]# #成人钢琴[话题]# #自学[话题]# #音乐[话题]# #流行歌曲[话题]# #颜值[话题]# #日常生活碎片[话题]# #好好生活皆如所愿[话题]# #下班后的日常[话题]# #今日份今日发[话题]# #求助[话题]# #种草[话题]# #好物推荐[话题]# #记录我的生活[话题]# #记录吧就现在[话题]# #日常[话题]# #日常plog[话题]# #兴趣[话题]# #想记录下此刻[话题]#', '', 1709034539000, 1709034539000, '332', '143', '66', '8', '\"http://sns-web-i10.rednotecdn.com/202606101825/959ea8c6d458c774d62f50ec3866d72d/1040g00830vm9dafsm4005n5r2hr5j86213cq2mg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/c93c1e7917e8de26f48018f2e6d2949f/1040g00830vm9dafsm40g5n5r2hr5j862fnbkchg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101825/e755cf2bd814da4ed30633930758dabd/1040g00830vm9dafsm4105n5r2hr5j862lgtiig8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u94a2\\u7434\\u8c03\\u5f8b,\\u96c5\\u9a6c\\u54c8,\\u96c5\\u9a6c\\u54c8\\u94a2\\u7434,\\u81ea\\u5b66\\u94a2\\u7434,\\u6210\\u4eba\\u94a2\\u7434,\\u81ea\\u5b66,\\u97f3\\u4e50,\\u6d41\\u884c\\u6b4c\\u66f2,\\u989c\\u503c,\\u65e5\\u5e38\\u751f\\u6d3b\\u788e\\u7247,\\u597d\\u597d\\u751f\\u6d3b\\u7686\\u5982\\u6240\\u613f,\\u4e0b\\u73ed\\u540e\\u7684\\u65e5\\u5e38,\\u4eca\\u65e5\\u4efd\\u4eca\\u65e5\\u53d1,\\u6c42\\u52a9,\\u79cd\\u8349,\\u597d\\u7269\\u63a8\\u8350,\\u8bb0\\u5f55\\u6211\\u7684\\u751f\\u6d3b,\\u8bb0\\u5f55\\u5427\\u5c31\\u73b0\\u5728,\\u65e5\\u5e38,\\u65e5\\u5e38plog,\\u5174\\u8da3,\\u60f3\\u8bb0\\u5f55\\u4e0b\\u6b64\\u523b\"', 'https://www.xiaohongshu.com/explore/65ddcc2a000000000702699b?xsec_token=ABHI-RGQW84wDlCxiklcT1voZWQL-sa3lE6F85jj5cnzE=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'ABHI-RGQW84wDlCxiklcT1voZWQL-sa3lE6F85jj5cnzE=');
INSERT INTO `xhs_note` VALUES (119, '60d7f5ff0000000001005585', '看到我请提醒我喝水', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3170c5ko63u605o6nunvg8lc56okrpkg', '', 1781087167265, 1781087167265, '6842a683000000002001c2e9', 'normal', '真搞不懂为什么电钢琴一定要选大品牌啊', '很多人觉得电钢琴嘛，随便买个便宜的能用就行，干嘛非要选雅马哈、罗兰、卡西欧、卡瓦依这些大品牌？其实真不是品牌溢价的问题，而是大品牌在音色、键盘手感、稳定性这些核心体验上确实更靠谱。\n	\n✅ 音色采样技术\n大品牌的电钢琴音色大多来自自家高端三角钢琴的采样，比如雅马哈的CFIIIS音乐会三角钢琴音源，卡西欧的AiR音源技术。这些音色经过专业录音室录制，听起来更自然、动态范围更广。而一些小品牌可能直接用合成音色，弹起来塑料感很强，甚至会出现“丢音”的情况。\n	\n✅ 键盘手感更接近真钢\n电钢琴的键盘决定了你的练习效果。大品牌通常采用逐级配重键盘（低音区重、高音区轻），比如雅马哈的GHS键盘、卡西欧的Scaled Hammer Action II技术，能模拟真实钢琴的触键反馈。而便宜的电钢琴可能只是“半配重”甚至“无配重”，弹久了转真钢会很不适应。\n	\n✅ 品控和售后更稳\n大品牌的电钢琴出厂前会经过严格测试，故障率低，而且售后网点多，维修方便。而一些小品牌可能用一段时间就出现按键失灵、音色失真等问题，修都没地方修。\n	\n✅ 复音数够用，不会“丢音”\n复音数决定了电钢琴能同时发出多少个音符。大品牌入门款通常128复音起步，而一些低价电钢琴可能只有64复音，弹复杂曲子时会出现音符突然消失的情况。\n	\n如果你刚开始学琴，电钢琴比真钢更友好——不占地方、不用调音、可以戴耳机练琴。推荐几款性价比高的入门电钢琴：\n1️⃣ 罗兰FP18 💰2650\nFP系列中体积最紧凑的全尺寸88键电钢琴。面板中文标识，上手更轻松。内置包括6种中国民乐音色在内的15种音色，演奏更有趣味。支持蓝牙MIDI，可连接学琴APP，学练更方便。\n2️⃣ 卡西欧PX-S1100💰3478\n拥有时尚镜面外观，荣获过世界权威IF设计奖和红点设计奖，颜值可以说是独一档，重量也非常轻便，还有蓝牙/触控液晶屏等智能设定。采用了逐级配重重锤键盘，整体触感接近真钢，可通过外接音箱或监听耳机。颜值党首选，外出携带绝对能成为现场焦点。\n3️⃣ 卡瓦依KDP-120 💰5291\n除了基本的192的复音数和逐级配重键盘，还搭载着卡哇伊的真三角钢琴音乐。最重要的是它带蓝牙midi功能，可以去和手机或平板产生更好的互联，有更好的体验。\n4️⃣ 雅马哈YDP165💰7089\n雅马哈GH3键盘，乌木黑键+合成象牙白键，防滑易于弹奏。CFX音源，充满爆发力和表现力。双20瓦的扬声器，高中低频的声音均衡调，音色富有表现力。\n	\n#电钢琴[话题]# #电钢琴推荐[话题]#', '', 1749198467000, 1749198468000, '315', '332', '2', '111', '\"http://sns-web-i10.rednotecdn.com/202606101826/8f5fb385bbdd163ffb537df40c6283e2/1040g00831icp28p708dg5o6nunvg8lc5vgdjp20!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u63a8\\u8350\"', 'https://www.xiaohongshu.com/explore/6842a683000000002001c2e9?xsec_token=ABO2zw7TFFBgkfvyupAc2e33xw9QwQzWEv8m33PrGUg4Q=&xsec_source=pc_search', '雅马哈电钢琴 活动价折扣', 'ABO2zw7TFFBgkfvyupAc2e33xw9QwQzWEv8m33PrGUg4Q=');
INSERT INTO `xhs_note` VALUES (120, '66c4251c000000001d020b10', '橙子🍊的学琴笔记', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31qtbhltlgm605pm44ke7c2oggnd2fjg', '', 1781087728847, 1781087728847, '675fea0c000000001300d67f', 'normal', '钢琴教材搭配一览💡', '学习钢琴需要循序渐进，从启蒙入门到高级阶段都有相应的教材搭配学习，不能一蹴而就。\n	\n🌟教材搭配\n1️⃣级：小汤1、小汤2、哈农\n2️⃣级：拜厄、小汤3、车尔尼139\n3️⃣级：车尔尼599、钢琴基础教程1、巴赫初级钢琴曲集\n4️⃣级：巴赫初级曲集、钢琴基础教程2、车尔尼718、柴可夫斯基少年曲集\n5️⃣级：车尔尼849、小奏鸣曲、钢琴基础教程3、巴赫小前奏曲与赋格\n6️⃣级：车尔尼849（快速）、巴赫三部创意曲、海勒钢琴练习曲、格里格66首抒情小品\n7️⃣级：车尔尼299、肖邦圆舞曲、克拉莫练习曲、格拉纳多斯浪漫钢琴曲集\n8️⃣级：车尔尼299（快速）、巴赫三部创意曲、海勒练习曲、海顿奏鸣曲\n9️⃣级：车尔尼740、肖邦夜曲集、莫斯科夫斯基钢琴练习曲、门德尔松无词歌\n🔟级：车尔尼740（快速）、肖邦练习曲、贝多芬奏鸣曲、李斯特大型乐曲、巴赫平均律\n	\n🌟学琴建议\n建议初学者入手电钢琴，它蕞大的优点就是能戴耳机练琴，孩子写完作业、成人下班回家，无论几点，只要你想，就能随时练琴，不用担心吵到邻居。只有练琴练的多了，才能把琴学好学会，俗话说勤能补拙嘛。而且电钢属电子产品范畴，使用寿命5-10年，也是足够了。\n❌初学者不要买电子琴/折叠琴，电子琴适合乐队、编曲，不适合作为钢琴的替代；折叠琴音色闷，琴键软，会毁手型。\n✅如果预算低，盲选卡西欧CDP-S110（1k+）PX-S1100（3k+），功能齐全，可玩性高，性价比非常高。\n✅如果预算高，追求键盘可考虑罗兰HP704，追求音源可考虑雅马哈CLP745。\n#电钢琴[话题]# #电钢琴推荐[话题]# #钢琴教材[话题]# #零基础学钢琴[话题]# #钢琴教学[话题]# #日常练琴[话题]# #学钢琴[话题]#', '', 1734339084000, 1734339085000, '2124', '2414', '16', '123', '\"http://sns-web-i10.rednotecdn.com/202606101834/7d3af0c34f8771d1ebcb78eeea048b40/1040g2sg31bfbi2pg0edg5pm44ke7c2oghj2o66o!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u94a2\\u7434\\u6559\\u6750,\\u96f6\\u57fa\\u7840\\u5b66\\u94a2\\u7434,\\u94a2\\u7434\\u6559\\u5b66,\\u65e5\\u5e38\\u7ec3\\u7434,\\u5b66\\u94a2\\u7434\"', 'https://www.xiaohongshu.com/explore/675fea0c000000001300d67f?xsec_token=ABlJk9S2H2HNx8mposZdmTzNC3VrqvdVszGPSiyzvK_v0=&xsec_source=pc_search', '雅马哈 YDP165 搬运重量', 'ABlJk9S2H2HNx8mposZdmTzNC3VrqvdVszGPSiyzvK_v0=');
INSERT INTO `xhs_note` VALUES (121, '66c4251c000000001d020b10', '橙子🍊的学琴笔记', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31qtbhltlgm605pm44ke7c2oggnd2fjg', '', 1781087728980, 1781087728980, '68ca7a060000000012017da4', 'normal', '学到钢琴十级需要多久？🎹', '很多人一开始学琴就盯着“十级”这个目标，但实际所需时间因人而异。一般来说，每天坚持练习1-2小时的情况下，从零基础到十级通常需要5-8年。不过具体进度还取决于个人天赋、练习效率和老师指导方式，有些人可能更快，也有些需要更长时间。\n	\n影响进度的因素有很多：比如练琴是否规律、是否重视基本功、是否理解乐理知识等等。考级本身不是目的，扎实掌握演奏能力才是关键。如果只是硬磕考级曲目，即使拿到证书，实际能力可能并不匹配。\n	\n学习过程中建议循序渐进，不要盲目追求速度。前期打好手型、节奏和识谱基础，中期注重音乐表现力，后期突破技术难点。每周保持至少5天练习，避免临时突击。\n	\n虽然传统钢琴手感好，但对多数家庭来说，电钢琴其实是更务实的选择。尤其是现代电钢琴的技术已经很成熟，键盘手感接近真钢，还能调节音量、佩戴耳机练习，不用担心吵到邻居。\n	\n如果想系统学琴又希望性价比高，推荐这几款立式电钢琴：\n1️⃣ 雅马哈YDP165💰7089\n雅马哈GH3键盘，乌木黑键+合成象牙白键，防滑易于弹奏。CFX音源，充满爆发力和表现力。VRM LITE虚拟共振建模技术，通过现代科技使声音听上去更丰富自然。双20瓦的扬声器，高中低频的声音均衡调，音色富有表现力，支持内录功能，音色细腻具有表现力，值得入手。\n2️⃣ 卡瓦依CN201💰7861\n采用RHC III键盘，197mm的键盘支点长度和立式钢琴一致，手感超赞，被称为同价位竞品中最接近立式钢琴的键盘。采用渐变谐波成像音源技术采样，相比KDP 系列的声音更贴合采样钢琴原款。此外，2个20w的扬声器功放非常震撼。\n3️⃣ 卡西欧AP-S450💰7989\n主打时尚纤薄，防尘盖带有缓降设计，触摸式的控制面板非常有质感。木塑混合的键盘在同价位中竞争力了非常强，256的复音数，26种内置音色，四十瓦两通道，四个扬声器，还有即时回放功能，弹完之后270秒以内的演奏都可以一键录音。\n4️⃣ 雅马哈P515💰9999\n88键重锤，重量20公斤，黑/白两色。键盘是木质的，很重，手感接近真钢，音源是雅马哈CFX和贝森多夫帝王钢琴帝王钢琴音色。515的新款525个人觉得键盘没有515好，如果预算充足，又想要一款便携电钢，515可选。\n#钢琴[话题]# #钢琴教育[话题]# #钢琴教材[话题]# #电钢琴[话题]# #电钢琴推荐[话题]# #零基础学钢琴[话题]# #钢琴练习[话题]# #钢琴入门[话题]#', '', 1758099974000, 1758099974000, '1852', '1963', '142', '221', '\"http://sns-web-i10.rednotecdn.com/202606101834/c2c902e554e9598ded285601fa217314/notes_pre_post/1040g3k031mhdkfjb4q6g5pm44ke7c2og7tdnur0!nd_dft_wlteh_webp_3?src=A\"', '\"\\u94a2\\u7434,\\u94a2\\u7434\\u6559\\u80b2,\\u94a2\\u7434\\u6559\\u6750,\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u96f6\\u57fa\\u7840\\u5b66\\u94a2\\u7434,\\u94a2\\u7434\\u7ec3\\u4e60,\\u94a2\\u7434\\u5165\\u95e8\"', 'https://www.xiaohongshu.com/explore/68ca7a060000000012017da4?xsec_token=ABI0Hl_vKuvQf-nb3YnFbGhHVzHHb8IdAPJKqnUuYWLko=&xsec_source=pc_search', '雅马哈 YDP165 搬运重量', 'ABI0Hl_vKuvQf-nb3YnFbGhHVzHHb8IdAPJKqnUuYWLko=');
INSERT INTO `xhs_note` VALUES (122, '5d97b1ad0000000001001ed0', 'Zzc_', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31fregh807e005ncnm6mg87mgnc1hvv0', '', 1781087729159, 1781089189297, '67ebb714000000001c02fe0d', 'normal', '一代人有一代的破烂：电钢琴', '其实我已经很多年没有正儿八经弹过琴了，就留学的时候无聊上了俩学期入门钢琴课，然后买了个雅马哈入门电钢玩了玩。但因为“我想要”这一句话，你二话不说的把它列入软装清单里，然后在某一天下班后拉着我去买琴。\n本来在家看上的还是雅马哈CLP785，到店里拿下的却是CLP885，不得不说你比销售还销售，一分钱一分货是你的至理名言，买新不买旧是你的人生哲理。\n就这样搬家一个多月了，老子一次琴都没摸过。一想到上班每天要生八万来次气，更不用说回家练琴了。看来只有哪天摆脱牛马的身份才能好好享受生活，静下心来练琴。\n希望这一天早日到来，求求了，我一定洗心革面、认真练琴，把失去的都捡回来。\n	\n#电钢琴[话题]# #电钢琴推荐[话题]# #雅马哈[话题]# #雅马哈电钢琴[话题]# #雅马哈clp885[话题]# #软装灵感[话题]# #软装分享[话题]# #不想上班[话题]# #不爱上班[话题]# #拒绝上班[话题]# #牛马日常[话题]# #牛马日记[话题]# #牛马人生[话题]#', '', 1743501076000, 1743501076000, '1232', '491', '342', '117', '\"http://sns-web-i10.rednotecdn.com/202606101834/ccc4b1ca6cb197087f16ecf3135fd7df/1040g00831fnsauiq7e005ncnm6mg87mgavsja60!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101834/8ef125a0f95431a2dd789735518b61f3/1040g00831fnsauiq7e0g5ncnm6mg87mggj5d2b8!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101834/eeebfd6091f8ce8a94519fae4f40d6ad/1040g00831fnsauiq7e105ncnm6mg87mgjmut1bg!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u96c5\\u9a6c\\u54c8,\\u96c5\\u9a6c\\u54c8\\u7535\\u94a2\\u7434,\\u96c5\\u9a6c\\u54c8clp885,\\u8f6f\\u88c5\\u7075\\u611f,\\u8f6f\\u88c5\\u5206\\u4eab,\\u4e0d\\u60f3\\u4e0a\\u73ed,\\u4e0d\\u7231\\u4e0a\\u73ed,\\u62d2\\u7edd\\u4e0a\\u73ed,\\u725b\\u9a6c\\u65e5\\u5e38,\\u725b\\u9a6c\\u65e5\\u8bb0,\\u725b\\u9a6c\\u4eba\\u751f\"', 'https://www.xiaohongshu.com/explore/67ebb714000000001c02fe0d?xsec_token=AB3cA-XboW0ZiSb4S_IndQGxw1XraiHZdtGaYZbFjQyOQ=&xsec_source=pc_search', '雅马哈 YDP165 搬运重量', 'AB3cA-XboW0ZiSb4S_IndQGxw1XraiHZdtGaYZbFjQyOQ=');
INSERT INTO `xhs_note` VALUES (123, '684cae93000000001b01b7b8', 'SUNN杉影', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31mitu208li005q2clq9mrdtog7ajla0', '', 1781087729349, 1781089189436, '6919c4ed0000000004013e96', 'normal', '富士xm5｜小黄奶油', '当富士xm5遇到了小黄奶油\n淡淡的颜色非常好搭配\n超轻重量，高手感握柄，极大提升握持体验\n	\n#富士[话题]# #富士xm5[话题]# #相机配件[话题]# #相机配件分享[话题]# #黄奶油[话题]#', '', 1763296493000, 1763296493000, '973', '291', '183', '174', '\"http://sns-web-i10.rednotecdn.com/202606101835/825986731e384da5a9b7d129dec8ef05/notes_pre_post/1040g3k831ouqjfoaha705q2clq9mrdto7v19roo!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/25bb714057561012f9a2b3ae54c15daf/notes_pre_post/1040g3k831ouqjfoaha7g5q2clq9mrdtouvkd910!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/942d19c79a3b4e03eb4be70f029c937d/notes_pre_post/1040g3k831ouqjfoaha805q2clq9mrdtobq4t4o8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u5bcc\\u58eb,\\u5bcc\\u58ebxm5,\\u76f8\\u673a\\u914d\\u4ef6,\\u76f8\\u673a\\u914d\\u4ef6\\u5206\\u4eab,\\u9ec4\\u5976\\u6cb9\"', 'https://www.xiaohongshu.com/explore/6919c4ed0000000004013e96?xsec_token=ABULVUP9L-EMpvAKWQ8EGDaMFQKQCPtDjrYbOft6rMDwY=&xsec_source=pc_search', '雅马哈 YDP165 搬运重量', 'ABULVUP9L-EMpvAKWQ8EGDaMFQKQCPtDjrYbOft6rMDwY=');
INSERT INTO `xhs_note` VALUES (124, '5e4e23840000000001006e35', '奇遇', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31okol3et506g5nie4e208rhlinv5u3o', '', 1781087729410, 1781089189491, '693d2a94000000001e00b1b1', 'normal', '「宝钱计划」我有一个宝钱梦（奇遇版🎁）', '周年庆啦，各位少侠宝钱都攒够了吗？在梦里，我的宝钱满仓，八音窍买到手软，通宝无限换……\n	\n【我的业务】\n⭐包周20，保底可打106.3🥣宝钱\n⭐包月80，保底可打455.6🥣宝钱\n⭐支持长期，一次可接9000🥣宝钱\n	\n【我的服务】\n⭐直播纯手工，直播间及群聊随机发放奇遇\n⭐3-5天一上号，不影响少侠正常游玩，不挤号\n⭐高效收益，屯菜一次性溢价50%抛出\n⭐支持宝钱定制\n	\n【我的保障】\n⭐奇遇的店已开，保证金已缴纳\n⭐背靠社群，人数超700+\n⭐百分百好评，质量保障\n⭐千粉博主，信誉有保证\n	\n#燕云十六声[话题]#\n#八音窍[话题]#\n#燕云十六声周年庆[话题]#\n#燕云十六声奇遇[话题]#\n#种草[话题]#', '', 1765616276000, 1772855195000, '966', '366', '324', '32', '\"http://sns-web-i10.rednotecdn.com/202606101835/b6fe8a10424032d8d26b51dc34719b7b/notes_pre_post/1040g3k831q1dm3tt74ug5nie4e208rhlld5vmdo!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/a2258f0e8780b62bf1e23c11b7969db7/notes_pre_post/1040g3k831q1dm3tt75005nie4e208rhla5kdk8o!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/db718b63b5776f4a4b05c8dd5b7e287f/notes_pre_post/1040g3k831q1dm3tt74u05nie4e208rhlv9tlmpo!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/e5809a0ce713ed3b8c1ab6b0b25c4991/notes_pre_post/1040g3k831q1dm3tt74vg5nie4e208rhlhvrvscg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/3d5f4c52930548d3e0bda8c5697cede7/notes_pre_post/1040g3k831q1dm3tt750g5nie4e208rhlslt8k40!nd_dft_wlteh_webp_3?src=A\"', '\"\\u71d5\\u4e91\\u5341\\u516d\\u58f0,\\u516b\\u97f3\\u7a8d,\\u71d5\\u4e91\\u5341\\u516d\\u58f0\\u5468\\u5e74\\u5e86,\\u71d5\\u4e91\\u5341\\u516d\\u58f0\\u5947\\u9047,\\u79cd\\u8349\"', 'https://www.xiaohongshu.com/explore/693d2a94000000001e00b1b1?xsec_token=AB0nOK-MPX2chAtidn7-chJocs8Q-oXBbOLZYL1Glcyco=&xsec_source=pc_search', '雅马哈 YDP165 搬运重量', 'AB0nOK-MPX2chAtidn7-chJocs8Q-oXBbOLZYL1Glcyco=');
INSERT INTO `xhs_note` VALUES (125, '5968a51650c4b40fe7a1794b', '长沙高级钢琴调音师', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo311qjguhv0mqg49m32jihcuab3u9g23g', '', 1781087729462, 1781087729462, '65f80f7e000000000d00c286', 'normal', '收藏一下，人还是要有梦想的，万一实现啦了', '施坦威钢琴型号，史上最全，一张图告诉你D、C、B、A、O、M、S、K、V分别代表多大尺寸。一文了解施坦威相关信息\nSteinway1853年诞生在美国纽约，总部位于纽约，在美国纽约和德国汉堡的两个工厂生产Steinway主品牌钢琴，创始人是德国移民施坦威，德国厂由施坦威儿子西奥多在汉堡创建\n施坦威共有9个基本型号（7款卧式钢琴和2款立式钢琴），2020年最新调整的零售价从人民币40万到180万不等\n施坦威三角型号：D274,C227,B211,A188,O180,M170,S155.目前还在产的立式施坦威只有K132一款，另外一款在K132基础上设计的缩小版，V125已于2022年停产。\n斯坦威旗下还有副牌如Boston、Essex、Langlang等，Essex、Langlang主要是珠江代工，不过多介绍\n#钢琴[话题]##施坦威钢琴[话题]# #三角钢琴[话题]##立式钢琴[话题]#', '', 1710755710000, 1710755710000, '944', '686', '16', '131', '\"http://sns-web-i10.rednotecdn.com/202606101835/dd23bbb40ac3fb3f1995cbd10cf00e86/1040g008310fu48oami6g49m32jihcuabp486jt8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/a689fafac34d4bab4b44d552c5e46529/1040g008310fu48oami6049m32jihcuabl7j3l1g!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/57662883a4260cdf37faaf88c7e468d6/1040g008310fu48oami5g49m32jihcuablkca4ng!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/d188477fa2f748588ba5c53e5eac83d6/1040g008310fu48oami4g49m32jihcuabfasi05o!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/da16f24bcadca49c06e173c140224a7f/1040g008310fu48oami4049m32jihcuab89u77o0!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/1d8d019975ac5703c107b62655c17100/1040g008310fu48oami3g49m32jihcuab13pk3s8!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/0e4140882d8ef07945e08541773aa542/1040g008310fu48oami3049m32jihcuabptnkgno!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/05c652cc657fb3a6d69b0acd8b0db5f2/1040g008310fu48oami2049m32jihcuabis9al1o!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/b0aee17522275b4b132a54b818bb582f/1040g008310fu48oami1g49m32jihcuab1732ce0!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/d501f06eb9f09d4413fd80207b0981aa/1040g008310fu48oami0g49m32jihcuabs0ctcgg!nd_dft_wgth_webp_3?src=A\"', '\"\\u94a2\\u7434,\\u65bd\\u5766\\u5a01\\u94a2\\u7434,\\u4e09\\u89d2\\u94a2\\u7434,\\u7acb\\u5f0f\\u94a2\\u7434\"', 'https://www.xiaohongshu.com/explore/65f80f7e000000000d00c286?xsec_token=AB_AXwmi_m0dxNzLBqNYwMIFzJDto-RkTMWoKEo5nnTz8=&xsec_source=pc_search', '雅马哈 YDP165 搬运重量', 'AB_AXwmi_m0dxNzLBqNYwMIFzJDto-RkTMWoKEo5nnTz8=');
INSERT INTO `xhs_note` VALUES (126, '60d7f5ff0000000001005585', '看到我请提醒我喝水', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3170c5ko63u605o6nunvg8lc56okrpkg', '', 1781087729567, 1781087729567, '678b60ea000000001c00ead4', 'normal', '每天练四个小时的琴，三年后会达到什么水准', '如果你每天玩4个小时钢琴，3年后会变成一个钢琴高手；\n如果你每天练4个小时钢琴，3年后会变成一个钢琴爱好者；\n如果你每天学4个小时钢琴，3年后会变成一个痛恨钢琴的人。\n	\n如果你能找一个优秀的老师，高效率练习4小时钢琴，那你三年可以弹完以下这些书：\n	\n1️⃣ 入门：拜厄（半年）\n2️⃣ 基础：车尔尼599，布格缪勒100，巴赫初步教程（半年）\n3️⃣ 初级：车尔尼849，布格缪勒109，巴赫二三部创意曲（选弹）小奏鸣曲集（选弹）（半年）\n4️⃣ 中级：车尔尼299，布格缪勒105，巴赫二三部创意曲，小奏鸣曲集（一年）\n5️⃣ 中级进阶：车尔尼740（选弹）小奏鸣曲集（半年）\n	\n举例说明：\n👉自学弹完740，你去弹十级的曲子，很难，弹一首10页的曲子，你要花半年才能弹出来，而且还不好听，没有触键技巧。\n👉找一般老师弹完740，弹十级10页的曲子，花三个月才能弹出来，也不怎么好听，一般老师也不怎么会教触键技巧。\n👉找优秀老师弹完740，弹十级10页的曲子，一个月可以弹出来，节奏整齐，音色均匀，想要更好听，练习一个月以上。\n	\n对于不想找老师、不想走专业路子的人，建议选琴首选电钢琴🎹。\n✔️电钢琴体积较小，不占空间，方便搬运和移动；功能强大，有调节音量、戴上耳机就能静音练习、多种音色、伴奏、节拍器等等功能；价位相对亲民，不需要调律，维护成本低。\n这里给大家分享几款口碑还不错的电钢琴：\n🌟雅马哈P145 💰2559\n雅马哈P-145是P系列中的入门级型号，是初学者的理想选择。这款纤薄的便携式数码钢琴只配备了必不可少的音色和功能，让您尽情享受原汁原味的演奏。\n🌟卡西欧PX-S1100💰3379\n这款颜值可以说是独一档，重量也非常轻便，还有蓝牙/触控液晶屏等智能设定。采用了逐级配重重锤键盘，整体触感接近真钢，可通过外接音箱或监听耳机。颜值党首选，外出携带绝对能成为现场焦点。\n🌟罗兰rp501💰5971\n88键重锤，128复音数。黑色/玫瑰木色可选，玫瑰木色看着很贵气。手感不错，堪比真钢，音色稍差一点，高音和低音不是特别悦耳，不过这个见仁见智吧，有些人就比较喜欢罗兰的音色。\n🌟卡西欧AP-S450💰8989\n是卡西欧高端立式电钢入门款，超薄外观，采样百万级三角钢琴音源，256复音数，拥有木塑混合键盘，手感反馈优秀，日常弹奏或考级练习非常合适。20w+20w功率，双通道四扬声器，音质很赞。\n#电钢琴[话题]# #电钢琴推荐[话题]# #零基础学钢琴[话题]# #钢琴[话题]# #成人学钢琴[话题]#', '', 1737187562000, 1737187562000, '878', '556', '12', '23', '\"http://sns-web-i10.rednotecdn.com/202606101835/fe2c81520aed9a33f6008171a7cb16e1/1040g00831cppqcbdgu6g5o6nunvg8lc5da9lnjg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/df8eb47981546d1b1d0c4efdf0b6cdf4/1040g00831cppqcbdgu605o6nunvg8lc5tabk3og!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/043e014dda8f1ea332ce30b732c6702f/1040g00831cppqcbdgu5g5o6nunvg8lc5cobgl8o!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/afcba5e65a74c826f1189cdf310a48da/1040g00831cppqcbdgu505o6nunvg8lc5kmuvlco!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u96f6\\u57fa\\u7840\\u5b66\\u94a2\\u7434,\\u94a2\\u7434,\\u6210\\u4eba\\u5b66\\u94a2\\u7434\"', 'https://www.xiaohongshu.com/explore/678b60ea000000001c00ead4?xsec_token=ABrhpsBm5yk9WGoSPblpSknd2ovJhxMlwivXLVRyHiiqw=&xsec_source=pc_search', '雅马哈 YDP165 搬运重量', 'ABrhpsBm5yk9WGoSPblpSknd2ovJhxMlwivXLVRyHiiqw=');
INSERT INTO `xhs_note` VALUES (127, '62dcb02e000000001e01f4cf', '我就是大机灵', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3203in531ii6g5omsm0n7jt6fg9rti7g', '', 1781087729607, 1781087729607, '66ef819600000000260339cf', 'normal', '电钢邮寄经验', '#电钢琴[话题]# #电钢琴邮寄[话题]# 邮寄过两次，都安全下车。第一次寄的德邦物流，路程特别远大概跨了两三个省，打了木架，木架钱120，一共邮费220多。邮寄到家实在是太重了，木架也没地方放。因此，第二次没有打木架，直接买箱子（电钢型号korg D 1，箱子尺寸140*30*30，40块钱和140*40*25，53块钱都买过，都能用。质量上真没啥差别。第一个尺寸稍微有点紧，琴的各种信息如图片显示）和缓冲气柱（30厘米50米完全够用。剩了特别多。）快递小哥说只要塞满了不晃，就没问题。我的顺序：琴外套气柱，气柱外套包装，包装外套三层气柱，气柱外套纸箱。走的京东物流，邻省，100来块钱，仍然安全到家。', '', 1726972310000, 1752405526000, '833', '742', '152', '345', '\"http://sns-web-i10.rednotecdn.com/202606101835/89b60edabe2f5bbfc4ba6e49293f1c4f/1040g2sg319nuu4hd7gn05omsm0n7jt6facn0h38!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/b2860bf1b6a1cb69181e43bf9eff51f1/1040g2sg3181ipsbl3q005omsm0n7jt6fl9klq6g!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/7eda924f2cd88e021a03135b6f37eb25/1040g2sg3181ipsbl3q0g5omsm0n7jt6fi9ulpj0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/ad7dc5a4677f420a2f7836768096d99f/1040g2sg3181ipsbl3q1g5omsm0n7jt6fc3haluo!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101835/c302c86d535818858413cac4d5c783de/1040g2sg31h9ssmn53q005omsm0n7jt6fiavb648!nd_dft_wgth_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u90ae\\u5bc4\"', 'https://www.xiaohongshu.com/explore/66ef819600000000260339cf?xsec_token=ABZLSJ18OsoFqopwYzCWhxIGDajRCSVwZQAj_F7dAzoTk=&xsec_source=pc_search', '雅马哈 YDP165 搬运重量', 'ABZLSJ18OsoFqopwYzCWhxIGDajRCSVwZQAj_F7dAzoTk=');
INSERT INTO `xhs_note` VALUES (128, '5bb368561f30bf0001699705', '生椰不拿铁', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31vtu868giq004b90f9k5d5o55cl5fqo', '', 1781087729643, 1781087729643, '693636e1000000001e03091a', 'video', '国外爆🔥的课前律动 让课堂更轻松', 'Warming up沉浸式热身小游戏，只需三分钟让课堂更轻松，学生不犯困[耶R][耶R][耶R]\n#课堂活跃气氛[话题]# #课前律动[话题]# #不一样课件[话题]# #课堂游戏[话题]# #趣味英语[话题]# #课堂互动[话题]# #课前热身[话题]# #互动游戏[话题]# #热身游戏[话题]##课件[话题]#', 'http://sns-video-bd.xhscdn.com/pre_post/1040g2t031pqjmmmokg704b90f9k5d5o53o8183o', 1765160673000, 1765613824000, '774', '763', '5', '412', '\"http://sns-web-i10.rednotecdn.com/202606101835/18cca1e0abe99ccf9f737ec60e9b31d6/1040g00831pqjmmmp4k004b90f9k5d5o5j7p79j0!nd_dft_wgth_webp_3?src=A\"', '\"\\u8bfe\\u5802\\u6d3b\\u8dc3\\u6c14\\u6c1b,\\u8bfe\\u524d\\u5f8b\\u52a8,\\u4e0d\\u4e00\\u6837\\u8bfe\\u4ef6,\\u8bfe\\u5802\\u6e38\\u620f,\\u8da3\\u5473\\u82f1\\u8bed,\\u8bfe\\u5802\\u4e92\\u52a8,\\u8bfe\\u524d\\u70ed\\u8eab,\\u4e92\\u52a8\\u6e38\\u620f,\\u70ed\\u8eab\\u6e38\\u620f,\\u8bfe\\u4ef6\"', 'https://www.xiaohongshu.com/explore/693636e1000000001e03091a?xsec_token=ABX_ZXUfbbhRTF6WfifnPladHP-aot79ipKCW3vWMtPJ8=&xsec_source=pc_search', '雅马哈 YDP165 搬运重量', 'ABX_ZXUfbbhRTF6WfifnPladHP-aot79ipKCW3vWMtPJ8=');
INSERT INTO `xhs_note` VALUES (129, '6707fe57000000001d021a65', 'Vinheteiro', 'https://sns-avatar-qc.xhscdn.com/avatar/670a51cf592ba12b7a0ecb1b.jpg', '', 1781088298121, 1781088298121, '695b4769000000000b009658', 'video', '听着难但其实很简单的歌', '#乐器大玩家[话题]# #学钢琴[话题]# #钢琴[话题]# #alanwalker[话题]# #李斯特[话题]#', 'http://sns-video-bd.xhscdn.com/spectrum/1040g35831qup8b8h70005po7vpbnc6j5tmotla8', 1767589737000, 1767589737000, '7.1万', '1.5万', '2354', '3915', '\"http://sns-web-i10.rednotecdn.com/202606101843/010c4a8ef356c5af097242d81827e3bd/spectrum/1040g0k031quqlleagm005po7vpbnc6j5pmjhrj0!nd_dft_wlteh_webp_3?src=A\"', '\"\\u4e50\\u5668\\u5927\\u73a9\\u5bb6,\\u5b66\\u94a2\\u7434,\\u94a2\\u7434,alanwalker,\\u674e\\u65af\\u7279\"', 'https://www.xiaohongshu.com/explore/695b4769000000000b009658?xsec_token=ABQnl8VfM3TRIKComlBMLwsHSdXFlwZutAHnbPNNGNDiU=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABQnl8VfM3TRIKComlBMLwsHSdXFlwZutAHnbPNNGNDiU=');
INSERT INTO `xhs_note` VALUES (130, '61a475cc000000001000d024', '多斐恩', 'https://sns-avatar-qc.xhscdn.com/avatar/6490fbf23d74fe6eda50a55d.jpg', '', 1781088298159, 1781088298159, '669f45d800000000270190b6', 'video', '买电钢琴主要原因还是怕扰民', '看过🧐网上很多吐槽的帖子，邻居吐槽楼上楼下练琴的噪音，或是被邻居投诉练琴影响小孩学习睡觉之类的这种矛盾。\n	\n电钢琴🎹可以随时随地根据需要调整音量大小，而不会对家人和邻居造成干扰，而且对那种需要不断调整试音的编曲创作也非常友好。\n当然除了静音功能，电钢琴还有录音、伴奏🎶、移调等各种功能，完美补足了真钢琴的不足之处，可能这也就是电钢琴的魅力吧。\n	\n👇视频末尾推荐的四款电钢琴，仅供参考。\n	\nwiyas EP-106  💰1899元\n	\n威雅斯EP-106是一款精心打造，适合初学者的便携式电钢琴🎹。轻巧的设计不仅便于移动，还能节省空间，特别适合那些练琴空间有限的用户。88键全尺寸重锤键盘，能够提供接近真实钢琴的弹奏体验，并且触键反应敏捷。高品质的大三角钢琴原声采样，音色温暖而细腻。128个复音数，能够满足不同阶段的演奏需求。这款电钢琴功能齐备，性价比很高，是便携式电钢琴中的优选✨。\n	\nKawai ES120  💰 3949元\n	\nES120外观设计具有一定的质感，配备逐级配重键盘和自家三角琴采样音色，很对喜欢卡瓦依钢琴温暖音色的玩家的胃口。25种音色，能满足大多数曲目的演奏需求，数码功能也比较全面。尺寸较小，适合小空间使用，但毕竟是入门款，如果练琴环境允许，建议这个价位购买立式的更好。\n	\nWiyas ep-109   💰2999元\n	\nWiyas EP109立式造型高端又大气，非常适合家庭使用。88键逐级配重键盘，准确模拟了真钢琴的手感。搭载进口音源芯片🎶，保证了音质的清晰与稳定，无延迟和丢音。它的音色来源于殿堂级大三角钢琴，通过40W大功率高保真扬声器播放，声音清晰层次丰富。复音数256个确保演奏流畅✨。支持智能设备连接，性价比💰在同类产品中脱颖而出。\n	\nRoland RP30  💰 4580元\n	\n三角钢琴音色采样而受到推崇，15种音色选择，88键逐级配重键盘，反应灵敏，接近真实钢琴的弹奏体验。128复音数确保了即使在快速弹奏时也不会出现音色丢失。电子功能如移调、重叠音色和节拍器一应俱全。对于预算充足且寻求初学和业余演奏需求的用户，RP30是一个参考选择。然而，对于追求更多流行音乐元素和丰富音色的用户来说，这款电钢琴🎹可能不太能满足他们的需求。\n	\n#钢琴[话题]#   #电钢琴[话题]#   #电钢琴入门[话题]#   #电钢琴选购[话题]#   #电钢琴推荐[话题]#   #电钢琴推荐平价[话题]#     #钢琴入门[话题]#   #钢琴怎么选[话题]#', 'http://sns-video-bd.xhscdn.com/spectrum/1040g0jg315j6u09n0k005od4en641k14qcu78v8', 1721714137000, 1742538482000, '1.3万', '2851', '98', '78', '\"http://sns-web-i10.rednotecdn.com/202606101843/3216d488d1c8d4bd54f32fea6ba7b0e8/spectrum/1040g0k0315j6unrl0s005od4en641k14v3obc7o!nd_dft_wlteh_webp_3?src=A\"', '\"\\u94a2\\u7434,\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u5165\\u95e8,\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u7535\\u94a2\\u7434\\u63a8\\u8350\\u5e73\\u4ef7,\\u94a2\\u7434\\u5165\\u95e8,\\u94a2\\u7434\\u600e\\u4e48\\u9009\"', 'https://www.xiaohongshu.com/explore/669f45d800000000270190b6?xsec_token=AB0-X7iiPv0VFDdxAYgiw30lIDYp3qQY-3kyhKwAlng8c=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'AB0-X7iiPv0VFDdxAYgiw30lIDYp3qQY-3kyhKwAlng8c=');
INSERT INTO `xhs_note` VALUES (131, '576d20617fc5b858ec8a045f', '一颗胖糖', 'https://sns-avatar-qc.xhscdn.com/avatar/576d20617fc5b858ec8a045f.jpg', '', 1781088298206, 1781088298206, '68948c820000000023035cf2', 'video', '雅马哈钢琴', '钢琴今天刚到家，发现高音不响，我家都不懂怎么看钢琴，请问这是正常的吗？调律是在10天后。', 'http://sns-video-bd.xhscdn.com/pre_post/1040g0cg31kso3gvdio0g48gub2g6212vvvn9280', 1754565762000, 1754565763000, '9527', '416', '1643', '675', '\"http://sns-web-i10.rednotecdn.com/202606101843/bf1f2451d647ce5102483a1bb1792545/1040g00831kso3gvi2u0g48gub2g6212vvkahi78!nd_dft_wlteh_webp_3?src=A\"', '\"\"', 'https://www.xiaohongshu.com/explore/68948c820000000023035cf2?xsec_token=ABaEG-kKoyAKfkyuSjz2HM8bmC040VWwQGy1uIQkuAUUQ=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABaEG-kKoyAKfkyuSjz2HM8bmC040VWwQGy1uIQkuAUUQ=');
INSERT INTO `xhs_note` VALUES (132, '62a81b87000000001b02b321', '龖貳醗鳌蒍', 'https://sns-avatar-qc.xhscdn.com/avatar/ae351b5abc78ae2e8d79998354db8440.jpg', '', 1781088298240, 1781088298240, '65b7c3b6000000002c035f5d', 'video', '世界上最难的钢琴曲，点个赞吧', '', 'http://sns-video-bd.xhscdn.com/pre_post/1040g2t030uh1v6gc581g5ol83e3mtcp13d9guso', 1706542006000, 1706542006000, '3300', '1380', '273', '172', '\"http://sns-web-i10.rednotecdn.com/202606101843/dc4f3491b0959ba6b7d9db0c1e49c65e/1040g00830uh21aa2l64g5ol83e3mtcp19crof9g!nd_dft_wlteh_webp_3?src=A\"', '\"\"', 'https://www.xiaohongshu.com/explore/65b7c3b6000000002c035f5d?xsec_token=ABt3b0zsasw204LkkVfIjDQD4fnT2izct3jDms3YKDQYY=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABt3b0zsasw204LkkVfIjDQD4fnT2izct3jDms3YKDQYY=');
INSERT INTO `xhs_note` VALUES (133, '561470ed3f95a306d442ad03', '咪咪御用麻麻', 'https://sns-avatar-qc.xhscdn.com/avatar/5f81486a1c4eb70001153e70.jpg', '', 1781088298275, 1781088298275, '65a91962000000002b017796', 'video', '自己听到的电钢声vs旁人听到的电钢音', '老公说我听起来在剁肉馅\n#电钢琴[话题]# #钢琴[话题]# #电钢内录[话题]# #雅马哈电钢琴[话题]# #键噪[话题]# #电钢琴键噪[话题]#', 'http://sns-video-bd.xhscdn.com/pre_post/1040g0cg30u2qb7u5l80041cgreoerb837vqs6j0', 1705580898000, 1705581795000, '2875', '427', '206', '1153', '\"http://sns-web-i10.rednotecdn.com/202606101843/20adb9abfbf7182270fb63ab10f49cfc/1040g2sg30u2qfgrblc0041cgreoerb83hnpgoig!nd_dft_wgth_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u94a2\\u7434,\\u7535\\u94a2\\u5185\\u5f55,\\u96c5\\u9a6c\\u54c8\\u7535\\u94a2\\u7434,\\u952e\\u566a,\\u7535\\u94a2\\u7434\\u952e\\u566a\"', 'https://www.xiaohongshu.com/explore/65a91962000000002b017796?xsec_token=ABtYu_Y-4CtyJjZjD88nFHQaZSRrV7p9ZWoz5UyljnVUQ=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABtYu_Y-4CtyJjZjD88nFHQaZSRrV7p9ZWoz5UyljnVUQ=');
INSERT INTO `xhs_note` VALUES (134, '66c5a903000000001d0235fd', '八月看晚霞', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo316onc1e0jm5g5pm5l41ncdft7in8790', '', 1781088298304, 1781089189015, '6878baaf000000001c030868', 'normal', '电钢琴测评合集', '❌罗兰FP10💰1890：功能太少，后续必须换琴\n✔️卡西欧CDP-S110💰1728：性价比高，便携\n❌ 雅马哈P48💰1899：琴键较软\n✔️ 卡西欧EP-S130💰2078：可考级，入门款\n✔️罗兰FP-18💰2650：性价比高\n❌卡瓦依KDP110💰2737：音色清脆，但配置较低\n❌ 卡瓦依ES-110💰2737：音色太尖锐\n❌ 卡西欧PX-S1000💰2757：热度高，但已经停产\n❌ 雅马哈P125💰2880：性价比较低\n✔️卡瓦依ES120💰3231：数码功能较全面\n✔️卡西欧PX-S1100💰3478：任何阶段都适用\n✔️雅马哈P225💰3587：音色明亮\n❌ 卡西欧PX-770💰3967：只比PX-870便宜了几百块配置却差了很多，喇叭功率小\n✔️罗兰FP-30X💰4120：键盘手感好\n8.卡西欧PX-870💰4278：4个喇叭音色非常好\n❌ 雅马哈YDP-105💰4989：入门级立式，有点低配了\n✔️卡瓦依KDP-120💰5291：2个20w扬声器外放效果很棒\n✔️罗兰RP-107💰6150：音色亮\n❌雅马哈YDP145💰6199：入门级立式，键盘不太行\n✔️卡瓦依CN201💰7861：手感好，键噪小\n✔️卡西欧AP-S450：音质很赞，木塑混合的键盘在同价位中竞争力了非常强\n❌ 卡西欧PX-S6000💰10599：配置不上不下\n✔️卡瓦依CA33💰12549：高端旗舰款\n✔️罗兰HP704💰13250：高配，还原真钢\n✔️雅马哈CLP745💰15950：音色手感都很好\n✔️卡西欧PX-S7000💰17478：贵价电钢推荐入\n#电钢琴[话题]# #钢琴[话题]# #电钢琴推荐[话题]# #电钢琴测评[话题]# #电钢琴选购[话题]# #电钢琴入门[话题]#', '', 1752742575000, 1752742576000, '2624', '2883', '107', '379', '\"http://sns-web-i10.rednotecdn.com/202606101844/423ebed1ba1f67fb23f86eee94c603e5/notes_pre_post/1040g3k831k1j0fp0iod05pm5l41ncdft3fm5cio!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/cc1e871ce82d686a3de85696aa109003/notes_pre_post/1040g3k031k1j0fqfiu6g5pm5l41ncdftpcoau28!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u7535\\u94a2\\u7434\\u6d4b\\u8bc4,\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u7535\\u94a2\\u7434\\u5165\\u95e8\"', 'https://www.xiaohongshu.com/explore/6878baaf000000001c030868?xsec_token=AB-33LnyQGGRjJKGLR2HTxYJdb6XYDf2k-xduKol1CCXA=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'AB-33LnyQGGRjJKGLR2HTxYJdb6XYDf2k-xduKol1CCXA=');
INSERT INTO `xhs_note` VALUES (135, '60d7f5ff0000000001005585', '看到我请提醒我喝水', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3170c5ko63u605o6nunvg8lc56okrpkg', '', 1781088298331, 1781088298331, '67176cc80000000016020c42', 'normal', '新手选电钢琴🎹这些琴千万别买‼️', '新手小白买电钢琴很容易被骗，一不小心就当了冤大头，🔺这里给大家整理一些内行人才知道的买琴注意⚠️事项，希望大家别走弯路！\n1️⃣ 不建议买折叠琴\n2️⃣ 雅马哈假货很多，要注意！\n3️⃣ 国产也有很多高性价比的品牌\n4️⃣ 新手不建议去某鱼市场买琴，或者其他\n国际大牌电钢琴。\n5️⃣ 1000以下的电钢琴不要选了\n6️⃣ 卡西欧CDP-S110是主流品牌里性价比坠高的琴。\n7️⃣ 买电钢琴前要去琴行试试音色和手感，不要买别人说好的，要买自己觉得合适的。\n8️⃣ 尽量用自己最高预算买琴，一分钱一分货。\n9️⃣ 国产品牌电钢杂牌太多，慎重买\n1️⃣0️⃣ 小孩子或者成人新手买琴，不要买太贵的，5000以内蕞适宜。\n1️⃣1️⃣ 键噪不是重点，一般电钢都有键噪\n1️⃣2️⃣ 新手学琴，首先考虑手感\n1️⃣3️⃣ 雅马哈更建议买1w+的琴\n1️⃣4️⃣ 罗兰FP18和FP30X是同样的键盘\n1️⃣5️⃣ 实体店买琴建议货比三家找个靠谱的琴行\n1️⃣6️⃣ 实体店也有卖假货的，要注意区分。\n1️⃣7️⃣ 琴包首选黑色，且要加厚的。\n1️⃣8️⃣ 买琴都会赠送配件，问清楚有哪些赠品\n1️⃣9️⃣ 卡西欧PX-S1100适合大多数人\n2️⃣0️⃣ 一款好琴更有练琴的动力学琴，一半靠勤奋，一半靠一款好琴。\n	\n🌈给大家分享几款比较热门的，时候新手用的琴：\n✅卡西欧PX-S1100💰参考价：3379\n外观标志性的红色非常亮眼，颜值高。小巧便携，不管是外出还是搬家都很方便。音色我很喜欢，不是那种很尖锐的声音。88键逐级重锤键盘，回弹很快，快速连弹不会丢音。\n·\n✅ 雅马哈P225 💰参考价：3487\nP-225 具有雅马哈顶级的音乐会三角钢琴 CFX的音色，采用虚拟共振建模（VRM）Lite 技术，复制了真实三角钢琴中每一瞬间的音色变化。全新的GHC（渐层式槌感紧凑）键盘（88键）。\n·\n✅ KORG SP280  💰参考价：4480\n小众品品牌，也是有一些比较好的产品的。sp280算是korg里的中端款，音色和音质都不错，自带琴架，送琴凳琴罩，midi线可连电脑用garageband。但是线下店比较少，维修点也比较少，不过好在这个牌子品控还不错，挺抗用的。\n·\n✅卡瓦依KDP120💰参考价：4995\n配备了改良的RHCII键盘，加SK-EX三角钢琴琴音，整体效果不错，常见接耳机和APP连接之类的功能也有，尽管KDP-120的体积相对轻巧，但其功能依然多，在音色、外观设计和功能等方面表现不错。\n——\n#电钢琴选购[话题]# #电钢琴[话题]# #电钢琴入门[话题]# #零基础学钢琴[话题]# #钢琴弹奏[话题]# #钢琴练习[话题]#', '', 1729588424000, 1729588424000, '2527', '1264', '345', '162', '\"http://sns-web-i10.rednotecdn.com/202606101844/f09fe64b57becba4debcd37e442505d0/1040g0083198i8o9el86g5o6nunvg8lc539rsthg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/41d823905bc4414e287cbb918f9fc93b/1040g0083198i8o9el8505o6nunvg8lc5dhvb7u8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u5165\\u95e8,\\u96f6\\u57fa\\u7840\\u5b66\\u94a2\\u7434,\\u94a2\\u7434\\u5f39\\u594f,\\u94a2\\u7434\\u7ec3\\u4e60\"', 'https://www.xiaohongshu.com/explore/67176cc80000000016020c42?xsec_token=ABKoHEAxXsoascB1ZsDNNtjI31_lKW9dHpSTuPzeddyuU=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABKoHEAxXsoascB1ZsDNNtjI31_lKW9dHpSTuPzeddyuU=');
INSERT INTO `xhs_note` VALUES (136, '62d3a3e4000000001501e7bc', 'Belieber', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31rm9c2gii8605omjkfi5bptsaddvdf0', '', 1781088298359, 1781088298359, '69ed93e200000000350276e3', 'normal', '升降号克死我了', '好烦啊为什么这么多升降号，虽然我知道只要记fa,do,so,re,la,mi,si但是总是一弹就忘记了，找不到键，我识谱也好慢啊，有没有调理方法#有时候真的很无助[话题]# #大脑一片空白[话题]# #不是哥们儿[话题]# #乐理[话题]# #轻轻地碎了[话题]# #发出尖锐的爆鸣声[话题]# #不用管我死活[话题]# #钢琴[话题]# #谁来教教我[话题]# #谁懂我的痛[话题]#', '', 1777177570000, 1777177571000, '2399', '1536', '242', '59', '\"http://sns-web-i10.rednotecdn.com/202606101844/fd2fa6dde0077fde5d2336600bf75dd0/notes_pre_post/1040g3k031vdmehpnjm5g5omjkfi5bptstuf0sfg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/de2df10d49a849fe0ea7604733a1272f/notes_pre_post/1040g3k831vdmehtqkcdg5omjkfi5bptseoqvd5o!nd_dft_wlteh_webp_3?src=A\"', '\"\\u6709\\u65f6\\u5019\\u771f\\u7684\\u5f88\\u65e0\\u52a9,\\u5927\\u8111\\u4e00\\u7247\\u7a7a\\u767d,\\u4e0d\\u662f\\u54e5\\u4eec\\u513f,\\u4e50\\u7406,\\u8f7b\\u8f7b\\u5730\\u788e\\u4e86,\\u53d1\\u51fa\\u5c16\\u9510\\u7684\\u7206\\u9e23\\u58f0,\\u4e0d\\u7528\\u7ba1\\u6211\\u6b7b\\u6d3b,\\u94a2\\u7434,\\u8c01\\u6765\\u6559\\u6559\\u6211,\\u8c01\\u61c2\\u6211\\u7684\\u75db\"', 'https://www.xiaohongshu.com/explore/69ed93e200000000350276e3?xsec_token=ABI1vlnTJYvtQ7VEZi6vhmakp7rKZxG0cEeRbqqg7GZmA=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABI1vlnTJYvtQ7VEZi6vhmakp7rKZxG0cEeRbqqg7GZmA=');
INSERT INTO `xhs_note` VALUES (137, '66c4251c000000001d020b10', '橙子🍊的学琴笔记', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31qtbhltlgm605pm44ke7c2oggnd2fjg', '', 1781088298389, 1781089189235, '673b02ec0000000007039cf6', 'normal', '深度总结2024电钢琴～（红黑榜）', '分享几个选购电钢琴的小技巧：\n❶个人觉得不差钱，决定买电钢的话，优选日本品牌。\n❷日本品牌的电钢技术成熟，能符合专业人士对于音色、手感的要求。\n❸如果预算吃紧、对外观有追求、不明确是否长期学习的成年人，可以考虑1k+价位的入门款，性价比高，外观时尚，即使很久不弹作为摆件也好看。\n❹如果预算＜1000，建议再攒攒钱，几百块没有能用的电钢。\n——\n分享几款优质的电钢琴：\n✅卡西欧PX-S1100：外观标志性的红色非常亮眼，颜值高。小巧便携，不管是外出还是搬家都很方便。键盘回弹迅速，比较跟手，弹复杂的曲子不会丢音。\n✅ 美得理UP-205：键盘逐级配重、5级力度响应、音色数）和扬声器外放（2个25w）确实参数足够扎实，价格更加接地气。\n✅ 卡瓦依KDP-120：除了基本的192的复音数和逐级配重键盘，还搭载着卡哇伊的真三角钢琴音乐。最重要的是它带蓝牙midi功能，可以去和手机或平板产生更好的互联，有更好的体验。\n✅罗兰F701：机身小巧，占地面积小，折叠琴盖和固定琴谱的设计前卫时尚。音色逼真、触感还原度高。\n	\n#电钢琴[话题]# #自学钢琴[话题]# #电钢琴选购[话题]# #今天你练琴了吗[话题]# #零基础学钢琴[话题]# #成人钢琴[话题]#', '', 1731920620000, 1735800406000, '1297', '1279', '172', '164', '\"http://sns-web-i10.rednotecdn.com/202606101844/d1722f30f5ad57752963bfebae954938/1040g2sg31c54c2kjg8605pm44ke7c2ogc9p9go8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u81ea\\u5b66\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u4eca\\u5929\\u4f60\\u7ec3\\u7434\\u4e86\\u5417,\\u96f6\\u57fa\\u7840\\u5b66\\u94a2\\u7434,\\u6210\\u4eba\\u94a2\\u7434\"', 'https://www.xiaohongshu.com/explore/673b02ec0000000007039cf6?xsec_token=AB8TkbVewDW-BaIRb3KKUPYT-u5owbUXDjPYhTwIRrJXA=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'AB8TkbVewDW-BaIRb3KKUPYT-u5owbUXDjPYhTwIRrJXA=');
INSERT INTO `xhs_note` VALUES (138, '58c3622150c4b468782afc54', 'Cc爱弹琴🎹', 'https://sns-avatar-qc.xhscdn.com/avatar/642ccd3359d97ae2381ca217.jpg', '', 1781088298422, 1781088298422, '671660fd000000001b02d3ee', 'video', '罗兰电钢vs雅马哈电钢 音色（均是外放音色）', '#罗兰电钢琴[话题]# #雅马哈钢琴[话题]# 今天去了实体店，选了一款雅马哈电钢进行测评，因为实体店展示的琴不是很多，所以只找到一台价位与罗兰最接近的雅马哈ydp。我自己用的是罗兰fp30X\n视频里面从音色、琴键的触感、到同一首歌，用不同的琴演奏是什么样的感觉进行了测评，两台琴都是在没有任何调音的情况下，都是外放的音色，大家感兴趣的可以看一下。#罗兰电钢vs雅马哈电钢[PK]#', 'http://sns-video-bd.xhscdn.com/pre_post/1040g0cg3197hcd4dku004998jch23v2k4aoabfg', 1729519869000, 1753374653000, '1247', '530', '150', '279', '\"http://sns-web-i10.rednotecdn.com/202606101844/37e5503c308e042d4c111f120b5fc28e/1040g00831982c1h354004998jch23v2ks7ta040!nd_dft_wgth_webp_3?src=A\"', '\"\\u7f57\\u5170\\u7535\\u94a2\\u7434,\\u96c5\\u9a6c\\u54c8\\u94a2\\u7434\"', 'https://www.xiaohongshu.com/explore/671660fd000000001b02d3ee?xsec_token=ABjT-a0gLds6GYBPpy785EAn5OHGTrM5JwMnJvHh_X5UY=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABjT-a0gLds6GYBPpy785EAn5OHGTrM5JwMnJvHh_X5UY=');
INSERT INTO `xhs_note` VALUES (139, '605afb53000000000101ca19', '骏纬文化', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31io1u4b0h4005o2qvd9gbigpvqiar78', '', 1781088298515, 1781088298515, '687480bd000000001d00e6d7', 'video', '一首曲子听完雅马哈两千到两万的电钢琴', '#电钢琴选购[话题]# #买钢琴[话题]# #雅马哈电钢琴[话题]# #钢琴选购[话题]# #电钢琴推荐[话题]# #电钢琴测评[话题]# #雅马哈钢琴[话题]# #电钢琴入门[话题]# #钢琴练习[话题]# #钢琴入门[话题]#', 'http://sns-video-bd.xhscdn.com/pre_post/1040g2t031jtetrt82oq05o2qvd9gbigpn8m002g', 1752465597000, 1752465598000, '959', '593', '107', '339', '\"http://sns-web-i10.rednotecdn.com/202606101844/bafd453ce11746bd336f246c1cce82f0/1040g2sg31jtetrt4341g5o2qvd9gbigpk9s4noo!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u4e70\\u94a2\\u7434,\\u96c5\\u9a6c\\u54c8\\u7535\\u94a2\\u7434,\\u94a2\\u7434\\u9009\\u8d2d,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u7535\\u94a2\\u7434\\u6d4b\\u8bc4,\\u96c5\\u9a6c\\u54c8\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u5165\\u95e8,\\u94a2\\u7434\\u7ec3\\u4e60,\\u94a2\\u7434\\u5165\\u95e8\"', 'https://www.xiaohongshu.com/explore/687480bd000000001d00e6d7?xsec_token=ABqtDxHauP58os20Q1YBSb9rRGVf2JhlXEhQ45jRcw-O0=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABqtDxHauP58os20Q1YBSb9rRGVf2JhlXEhQ45jRcw-O0=');
INSERT INTO `xhs_note` VALUES (140, '606e775a000000000101d757', '🌸', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3170fum60466g5o3eetd0blqntoljjno', '江苏', 1781088298547, 1781088298547, '69fe9a800000000020039761', 'normal', '为什么现在很多博主都用电钢，不用真钢', '跟着博主推荐买了卡西欧的pxs1100[笑哭R]我也理解了为什么不用真钢了，电钢琴方便又好打理，而且这款手感又和真钢相似#电钢琴[话题]# #成人钢琴[话题]# #零基础学钢琴[话题]# #乐器[话题]# #钢琴[话题]#', '', 1778293376000, 1780967993000, '903', '613', '748', '34', '\"http://sns-web-i10.rednotecdn.com/202606101844/2a888f90b9381b73810b15a2ca6a0565/1040g00831vuajajo2i6g5o3eetd0blqnlsm60i0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/56c00fd8da7ef666ffc64199e09aa3e0/1040g00832165uoqq7e005o3eetd0blqnhq7e28g!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u6210\\u4eba\\u94a2\\u7434,\\u96f6\\u57fa\\u7840\\u5b66\\u94a2\\u7434,\\u4e50\\u5668,\\u94a2\\u7434\"', 'https://www.xiaohongshu.com/explore/69fe9a800000000020039761?xsec_token=ABV3_N0thVvSd1rjaztALUG_cO1vF4qKNgMDfQDQ8EgYQ=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABV3_N0thVvSd1rjaztALUG_cO1vF4qKNgMDfQDQ8EgYQ=');
INSERT INTO `xhs_note` VALUES (141, '53f4ba98b4c4d64fb3a363bb', 'momo', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31k7n8h7f320040058qt9gotrmqqe6vg', '', 1781088298615, 1781088298615, '689234bc00000000030257e9', 'normal', '用了快一年的雅马哈CLP-875，实话实说', '🎹去年10月决定学弹琴，去琴行看钢琴，第一眼就看上了这台雅马哈CLP-875电钢琴，看了它以后别的比它低一点的就有点看不上了，用到现在快一年，感觉这钱花得挺值。它不是那种“哇好炫酷”的琴，但实在地让练琴变得舒服、有动力。最让我喜欢的几个点：\n1.  这琴键，真像在弹真钢琴！去店里也试过别的电钢，手感轻飘飘的像玩具。CLP-875的琴键沉甸甸的，按下去有明显的阻力感，回弹也很有劲儿。手指能清晰感觉到那种细微的咔哒反馈，销售跟我说这台电钢琴模拟的是三角钢琴的感觉，练久了手指是真的会累、会酸，跟我每周去找老师上课弹的真钢感觉很像，这种扎实的触感，是督促我好好练基本功的动力，而且回课时候不会觉得弹真刚不习惯。\n2.  声音好听，戴耳机真的特别好听！外放的声音很饱满，特别是低音区，有那种嗡嗡的、好听的共鸣感，不像有些电钢声音很薄的、塑料感重，但最让我喜欢的是戴耳机的效果！夜深人静插上耳机弹，细节做的特别好，琴弦震动的余音、踩下延音踏板后那种空间回荡的感觉，特别清晰真实。当时就是冲这深夜练琴不扰民还能沉浸其中的效果买的，现在觉得值了。雅马哈那个技术我也不太懂，但戴上耳机确实能听出差别。\n3.  看着顺眼，摸着也很舒服，我选的深木纹哑光面，放家里不突兀，看着挺高级，不像个塑料玩具。琴键按下去可以从侧面看到是光滑的木头，摸着比塑料舒服太多了。当初选择电钢琴也是考虑了，不用像真钢那样隔几个月就请人来调音，插电就能弹，音量还能调，对于又上班又有娃的人来说，只有晚上这点时间了，所以电钢是我们不扰民，又能自己弹的开心的不二之选。功能也够用，自带的节拍器、还有很多乐器的音色，也可以连接iPad练习弹琴内录，其他功能我暂时还没使用过，但是功能是真多。\n最后大实话：\n贵吗？确实不便宜。 买的时候确实纠结了一下，怕买完了自己三天热乎劲过了，就不弹了。\n后悔吗？完全不。想想它能用很多年（雅马哈质量信得过），省了调音的钱，还解决了练琴时间自由和扰民的大问题。最关键的是，这手感和音色，让我每天坐下来练琴时，真的感觉是在弹钢琴，而不是在敲电子设备。这种沉浸感和满足感，是它最大的价值。\n适合谁？如果你：\n对钢琴手感有要求，不想弹“电子玩具感”的键盘，\n需要一台音色好、能戴耳机安静练习的琴，\n想要一台放家里好看、省心（不用调律）、能长久陪伴的乐器，\n预算能接受这个价位段。\n那CLP-875绝对特别适合。', '', 1754412220000, 1767606129000, '790', '609', '194', '155', '\"http://sns-web-i10.rednotecdn.com/202606101844/7275d6d8875c3834657389980a2e8df7/1040g2sg31kqf0c99j08040058qt9gotrb4k1t1o!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/8d39da374f8cfe8ed7c0f5b8fb41ca18/1040g2sg31kqf0c99j07g40058qt9gotr2dun8mg!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/d03f2865df0d07436d3852715b677f6b/1040g2sg31kqf0c99j09g40058qt9gotrd53bsa8!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/2755ef9e262920074429e5b8cc82ecba/1040g2sg31kqf0c99j08g40058qt9gotrlp3aap0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/531f431999977ce2e146012c9eb7afce/1040g2sg31kqf0c99j09040058qt9gotr1fpcomg!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/1a5a192781d4ecde4859ed7ec29bbdba/1040g2sg31kqf0c99j07040058qt9gotrnd6d600!nd_dft_wgth_webp_3?src=A\"', '\"\"', 'https://www.xiaohongshu.com/explore/689234bc00000000030257e9?xsec_token=AB5Du1M9YskiLQSs2uH_k-X5ydKFSvgov5L0Wgl5V1t2U=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'AB5Du1M9YskiLQSs2uH_k-X5ydKFSvgov5L0Wgl5V1t2U=');
INSERT INTO `xhs_note` VALUES (142, '5af68abde8ac2b4f65980e0f', '李开箱', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31bfj9rvg0s604a58oj5bq3gfr00j850', '', 1781088298645, 1781088298645, '65d44a1c0000000007005033', 'normal', '电钢琴有几个琴键不响怎么办？小红书好视频', '电钢琴放置很久有几个琴键不响怎么办？\n我电钢琴好久没用，有四个按键不出声，昨晚我搞了三个小时，终于搞定！\n电钢琴放置很久容易出一些问题，比如进一些灰等，造成琴键不响。\n先尝试多次重新接电源按开关，如果还不行，那可以采取以下措施:\n1.整理线:可以拆开盖板，拧下后面的螺丝即可，理一理线，看看有没有线压住，这时候尝试打开开关，试一下琴有没有声音。\n2.拔插各个接口，如果第一步没有声音，那可以插拔一些接口，拔下来，再插上去，打开开关试一下琴有没有声音\n以上两步是最简单的，下面则是需要拆琴键了。\n3.清理导电胶，这是大多数电钢琴某个键没声音的原因，导电胶在琴键的下面，刚开始可以先只拆没声音的几个琴键，用扁头螺丝刀在前面撬一下，注意别弄断了，看一下你的琴键能否取下，如果不能，则需要把琴主体下面的螺丝都拆下来，这样拉一下琴键，就能拆下来，能看到灰色的一些橡胶东西，这些就是导电胶了，你可以通电，按一下，就能发出声音hhhh，通常来说很多是导电胶的问题，这时候我们可以先拔下那几个导电胶，不用全部拔下来，用酒精棉擦一下导电胶那两个黑点点，以及主板的接触面，尝试打开开关，试一下声音，这一步，可以解决大多数电钢琴琴键没声音。\n4.更换导电胶，在更换导电胶之前，需要排除一下是不是导电胶的问题，可以多拆几个琴键，把正常响的琴键下面的导电胶取下，放在不响的琴键下面，如果响了，那证明是导电胶的问题，清洗之后还不行，那就需要更换了，网上很便宜，十几块钱几十块钱的。\n5.以上步骤都是可以自己动手维修，如果都不行，那可能就是主板的问题，需要找维修师傅来了！\n敲门:按导电胶的时候可以找一个细长的东西，比如我用的手机取卡针，不过太细了也不行，容易扎透，这个需要自己不断控制力度。\n好了，祝各位都能修好自己的电钢琴！\n#电钢琴[话题]# #钢琴[话题]# #电钢琴维修[话题]# #钢琴维修[话题]# #小红书视频好有意思[话题]# @视频薯', '', 1708411420000, 1708576416000, '777', '719', '73', '420', '\"http://sns-web-i10.rednotecdn.com/202606101844/3b25ffc7e568ab13d376a6cc783722d9/1040g00830vd099s3m25g4a58oj5bq3gftg3mcdg!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/0388a491fc256c07514bc83887a9f81f/1040g00830vd099s3m2504a58oj5bq3gfcu2fe5g!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/468eeac73ba98811c1169fe7da0ba7c9/1040g00830vd099s3m2404a58oj5bq3gfsg1m6mg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/4064aeff79d986adbe7eb4542e60ef31/1040g00830vd099s3m23g4a58oj5bq3gf6bi87n0!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/e2dbcbedb148ac48385cee411045a163/1040g00830vd099s3m26g4a58oj5bq3gfomfogio!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/f92701ead86bbb71bc9566d9f0c40220/1040g00830vd099s3m2104a58oj5bq3gf7lsebng!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101844/fcae526b2c8d975824d8ed3210bab20f/1040g00830vd099s3m2304a58oj5bq3gfdje2u68!nd_dft_wgth_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u7ef4\\u4fee,\\u94a2\\u7434\\u7ef4\\u4fee,\\u5c0f\\u7ea2\\u4e66\\u89c6\\u9891\\u597d\\u6709\\u610f\\u601d\"', 'https://www.xiaohongshu.com/explore/65d44a1c0000000007005033?xsec_token=ABps50rIHF0pA5gVkarqCtmTjLNtFTr7dUM9WgLceI44g=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABps50rIHF0pA5gVkarqCtmTjLNtFTr7dUM9WgLceI44g=');
INSERT INTO `xhs_note` VALUES (143, '5f89cd00000000000100af8b', 'momo', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo31q2rtg2ang605ns9pk009bsbeublm8g', '', 1781088298679, 1781088298679, '678a4bd0000000001c00caea', 'normal', '罗兰fp30x', '以为琴键比真钢轻很多呢，结果比我的老真钢还重！手感真是不错，质感也非常好，就是这玩意儿不算消遣了，弹了一会儿就累得觉得我是十年前那个绝望琴童。\n白色是真的美貌，就是这个音色，真比我想的差了很多很多，以前对电子音没有实感，到手发现，入门款电钢声音真的没有空间感和震动，很电子。\n建议买丐版，自己搞配件，淘宝店送的琴凳耳机啥的质量差到不忍直视。\n	\n#fp30x[话题]# #罗兰fp30x电钢琴[话题]# #电钢琴[话题]#', '', 1737116624000, 1737118741000, '777', '653', '175', '48', '\"http://sns-web-i10.rednotecdn.com/202606101844/3f5e527ef0fcdbc6f8f0c6d69d90e62d/1040g00831convv0vgu005ns9pk009bsbeojci1g!nd_dft_wgth_webp_3?src=A\"', '\"fp30x,\\u7f57\\u5170fp30x\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\"', 'https://www.xiaohongshu.com/explore/678a4bd0000000001c00caea?xsec_token=AB80foOF5zPU70yRKo1UHwnfwEf649gjU9M3L-HymJ2cQ=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'AB80foOF5zPU70yRKo1UHwnfwEf649gjU9M3L-HymJ2cQ=');
INSERT INTO `xhs_note` VALUES (144, '627e895800000000210200bb', '哇卡哇卡', 'https://sns-avatar-qc.xhscdn.com/avatar/6607b0cf3428ea0001a1626e.jpg', '', 1781088298741, 1781088298741, '68b6bd53000000001b031bd1', 'video', '9.9💰的超萌收纳包！！可爱又实用🤩', 'a6尺寸滴收纳包来啦~\n各种手帐用品a6贴纸小本本都可以放！外出旅行也可以当护照包哦~\n#四叶草[话题]#  ﻿#文创[话题]# ﻿  ﻿#收纳包[话题]# ﻿  #护照夹[话题]# ﻿#手帐[话题]# ﻿  ﻿#手帐好物[话题]# ﻿  ﻿#手帐收纳[话题]# ﻿ #手帐er的日常[话题]#  #手帐控[话题]# #萌物[话题]#', 'http://sns-video-bd.xhscdn.com/spectrum/1040g2f031lu49ar24s005ojuh5c8c05rp0ul58o', 1756806694000, 1756806694000, '708', '157', '7', '34', '\"http://sns-web-i10.rednotecdn.com/202606101844/c76c551127433b5e98a94a27ea85671a/1040g2sg31lu4tqh452e05ojuh5c8c05rg7cguj0!nd_dft_wlteh_webp_3?src=A\"', '\"\\u56db\\u53f6\\u8349,\\u6587\\u521b,\\u6536\\u7eb3\\u5305,\\u62a4\\u7167\\u5939,\\u624b\\u5e10,\\u624b\\u5e10\\u597d\\u7269,\\u624b\\u5e10\\u6536\\u7eb3,\\u624b\\u5e10er\\u7684\\u65e5\\u5e38,\\u624b\\u5e10\\u63a7,\\u840c\\u7269\"', 'https://www.xiaohongshu.com/explore/68b6bd53000000001b031bd1?xsec_token=ABjIUQjykytEHyyUZ6V0O8uTLas3j-LutzY8mAlAbC2Ho=&xsec_source=pc_search', '雅马哈电钢琴 弱音难控制', 'ABjIUQjykytEHyyUZ6V0O8uTLas3j-LutzY8mAlAbC2Ho=');
INSERT INTO `xhs_note` VALUES (145, '60d7f5ff0000000001005585', '看到我请提醒我喝水', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo3170c5ko63u605o6nunvg8lc56okrpkg', '', 1781089188914, 1781089188914, '6773a80f000000000b00e504', 'normal', '新手选电钢琴，有这张图就够了！', '每个价位不会踩坑的品牌型号如上✔️\n	\n初次买琴还是要注意控制预算\n通常电钢琴价位分成这几类\n1️⃣ 第一梯队：1000-3000💰，适合刚刚入门的小白，对于还不确定以后能不能学的下去的宝子特别合适，因为是大品牌琴不想弹了也容易出，可以考级使用～\n2️⃣ 第二梯队：3000-5000💰，适合学过琴的，或者打算长久学琴的宝子，一般这类琴可以说或是便携琴的顶配了\n3️⃣ 第三梯队：5000-8000💰，适合打算专业学琴，买回去方便练琴的，这个价位都是立式电钢，无论是手感还是音质都比便携琴好很多\n4️⃣ 第四梯队：8000+💰，适合专业学琴，预算又高的宝子，这个价位的电钢足矣媲美真钢了\n	\n✅✅✅以下是我个人比较推荐的型号：\n【追求性价比】卡西欧EP-S130：卡西欧的音色偏midi数码感，小巧轻薄，和110对比主要是可内录、双钢琴、可连接三踏板，红色外观太讨喜，如果是外观控可入，做工也很好，虽然是基础配置，但考级也完全可用。\n·\n【追求音色音质】罗兰F701：机身小巧，占地面积小，折叠琴盖和固定琴谱的设计前卫时尚。音色逼真、触感还原度高。\n·\n【追求手感】卡瓦依CN201：采用RHC III键盘，197mm的键盘支点长度和立式钢琴一致，手感超赞，被称为同价位竞品中最接近立式钢琴的键盘。采用渐变谐波成像音源技术采样，相比KDP 系列的声音更贴合采样钢琴原款。此外，2个20w的扬声器功放非常震撼。\n·\n【贵价不差钱】雅马哈P515：88键重锤，重量20公斤，黑/白两色。键盘是木质的，很重，手感接近真钢，音源是雅马哈CFX和贝森多夫帝王钢琴帝王钢琴音色。515的新款525个人觉得键盘没有515好，如果预算充足，又想要一款便携电钢，515可选。\n——\n#电钢琴[话题]# #电钢琴推荐[话题]# #零基础学钢琴[话题]# #钢琴[话题]# #成人钢琴[话题]#', '', 1735632911000, 1735632911000, '6085', '5666', '436', '1036', '\"http://sns-web-i10.rednotecdn.com/202606101858/5aaa12883f79606f5e26be120e7d2567/1040g00831c2kg9mi10dg5o6nunvg8lc541mvck8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u96f6\\u57fa\\u7840\\u5b66\\u94a2\\u7434,\\u94a2\\u7434,\\u6210\\u4eba\\u94a2\\u7434\"', 'https://www.xiaohongshu.com/explore/6773a80f000000000b00e504?xsec_token=AB_nschq0eNGaTyu_BGWsR92oDgR3kd3hgRl39SL4T_ZU=&xsec_source=pc_search', '雅马哈 YDP165 性价比', 'AB_nschq0eNGaTyu_BGWsR92oDgR3kd3hgRl39SL4T_ZU=');
INSERT INTO `xhs_note` VALUES (146, '57bc61bc6a6a69730797f6b2', 'BlueBlue', 'https://sns-avatar-qc.xhscdn.com/avatar/57bc61bc6a6a69730797f6b2.jpg', '', 1781089189144, 1781089189144, '675113090000000007027455', 'normal', '大龄女青年入坑梦中情琴🎹', '随着年龄增长，心里伴随小时候没坚持学钢琴的遗憾愈发强烈\n	\n前阵子看到了零基础自学乐理的视频，博主西蒙说得非常系统全面，通俗易懂且条理清晰，他试图说明白我！哈哈哈哈！他做到了！！！\n	\n我开始变得不由自主的坚持学习下去，从而萌生了强烈的欲望去弥补自己的遗憾。\n	\n开始刷了各种小红书电钢推荐视频，各品牌对比，还有如何成人自学等等等～最后找到了适合自己的高性价比的电钢。\n我知道对于初学者并不需要这么高的配置，但是我比较念旧，觉得在自己能力范围买最好的，并且一直用下去很多年，也是一个不错的选择。\n	\nCLP735这款，听说很接近真实钢琴的手感和声音，我也不确定是不是，但我确定心动了💗被其颜值和质感深深吸引！\n	\n听说这个琴还有可能炸音各种问题，正好在黑五买还有琴行延期保险，雅马哈也有自己的保险，听着还不错～就冲了\n	\n说实话，30+从零开始学什么都难，还有每天鸡毛蒜皮的小事和当不完的牛马。但是总比60岁之后还继续安慰自己，什么时候开始都不晚强一点点～\n	\n学习乐理这段时间，我找到了内心的平静，少了点浮躁。\n找到了新的治愈方式，决定继续逼一逼自己，坚持下去～\n	\n#钢琴选购[话题]# #有点小贵但很值[话题]# #为情怀买单[话题]# #电钢琴[话题]# #音乐治愈生活[话题]# #雅马哈电钢琴[话题]# #CLP735[话题]##成人零基础钢琴[话题]##自学钢琴[话题]##乐理自学[话题]# @三分钟音乐社', '', 1733366537000, 1748040638000, '1798', '1565', '120', '88', '\"http://sns-web-i10.rednotecdn.com/202606101859/ae0037a2a915a9e0a9a2e2ab4c6c7eaf/1040g2sg31b0rq38a7i0g48lfddgrptlijdj7hgo!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101859/6817795ea18125e1427df0e00efa7ec8/1040g2sg31b0rq38a7i0048lfddgrptlibq8cqpg!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101859/1fd4b0d6065b6a92730c9b1a2994afa3/1040g2sg31b0rq38a7i1048lfddgrptlidh4ogl8!nd_dft_wlteh_webp_3?src=A\"', '\"\\u94a2\\u7434\\u9009\\u8d2d,\\u6709\\u70b9\\u5c0f\\u8d35\\u4f46\\u5f88\\u503c,\\u4e3a\\u60c5\\u6000\\u4e70\\u5355,\\u7535\\u94a2\\u7434,\\u97f3\\u4e50\\u6cbb\\u6108\\u751f\\u6d3b,\\u96c5\\u9a6c\\u54c8\\u7535\\u94a2\\u7434,CLP735,\\u6210\\u4eba\\u96f6\\u57fa\\u7840\\u94a2\\u7434,\\u81ea\\u5b66\\u94a2\\u7434,\\u4e50\\u7406\\u81ea\\u5b66\"', 'https://www.xiaohongshu.com/explore/675113090000000007027455?xsec_token=AB_ArFTeBDEDrK9Su-LHqYmhDShaDqKZarnlQM9JfkIvE=&xsec_source=pc_search', '雅马哈 YDP165 性价比', 'AB_ArFTeBDEDrK9Su-LHqYmhDShaDqKZarnlQM9JfkIvE=');
INSERT INTO `xhs_note` VALUES (147, '643e5263000000000d01b8aa', '音音细韵', 'https://sns-avatar-qc.xhscdn.com/avatar/650bfbcc51244300016e46aa.jpg', '', 1781089189266, 1781089189266, '69b66b340000000022025545', 'video', '过来人忠告：电钢琴别乱买，看完少走弯路', '新手买电钢琴🎹容易踩的坑我就不多说了，直接给大家整理了目前口碑和热度都在线的型号，仅供参考，按需选就好。\n	\n✅【便携式推荐】\n	\n威雅斯EP106(1899元)：性价比在线💦，特别适合零基础入门。这个价位里，手感和音色都很能打，日常练琴完全够用。\n	\n罗兰FP18(3200元)：体积小，带起来方便，音质还不错✨，就是有点键噪，要是不介意配置简单点，也能入。\n	\n✅【立式推荐】\n	\n威雅斯EP109（2899元）：颜值高，不少博主都实测推荐🎗。搭载三角钢琴级音色，功能齐全，家用练琴、考级都能满足。\n	\n卡瓦依KDP120（4569元）：音色和音质都很扎实👀，手感接近真钢琴，立式外观质感在线。5000 元左右价位里综合实力很强，值得考虑。\n	\n雅马哈YDP145（6499元）：音色清亮通透✨，喜欢偏亮音色的可以选。预算充足的话，也可以直接上升级款 YDP165。\n	\n﻿﻿#电钢琴[话题]# ﻿  ﻿#电钢琴推荐[话题]# ﻿  ﻿#wiyas威雅斯ep109[话题]# ﻿  ﻿#wiyas电钢琴[话题]# ﻿  ﻿#钢琴[话题]# ﻿  ﻿#威雅斯电钢琴[话题]# ﻿  ﻿#电钢琴选购[话题]# ﻿  ﻿#电钢琴88键重锤推荐[话题]# ﻿', 'http://sns-video-bd.xhscdn.com/spectrum/1040g0jg31tnqo5db6o005p1ua9hjbe5a0h3tm90', 1773562676000, 1773563112000, '1235', '1075', '37', '94', '\"http://sns-web-i10.rednotecdn.com/202606101859/8d2e51ef183bff7d5f34800cbd21bd04/spectrum/1040g0k031tnqp4o1g4005p1ua9hjbe5a6v6sisg!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u63a8\\u8350,wiyas\\u5a01\\u96c5\\u65afep109,wiyas\\u7535\\u94a2\\u7434,\\u94a2\\u7434,\\u5a01\\u96c5\\u65af\\u7535\\u94a2\\u7434,\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u7535\\u94a2\\u743488\\u952e\\u91cd\\u9524\\u63a8\\u8350\"', 'https://www.xiaohongshu.com/explore/69b66b340000000022025545?xsec_token=AByU6kVhmjjIToi4LiiojYRxmaWeipwPH32fTIjjJQLS4=&xsec_source=pc_search', '雅马哈 YDP165 性价比', 'AByU6kVhmjjIToi4LiiojYRxmaWeipwPH32fTIjjJQLS4=');
INSERT INTO `xhs_note` VALUES (148, '57877554bd0da529d9190975', '西大调米小调', 'https://sns-avatar-qc.xhscdn.com/avatar/662927cd7f63bb4d3c96b372.jpg', '', 1781089189464, 1781089189464, '675aaaba000000000600ca85', 'normal', '钢琴老鸟说真话🎹电钢和真钢怎么选？', '最近身边有很多成年人都在学钢琴，不少人纠结：\n到底选电钢、真钢，还是一步到位上三角？\n作为同时用过这三种钢琴的业余老鸟，来分享我的一些心得👇🏻\n	\n1️⃣电钢琴\n优点：入手门槛低，静音不扰民💤\n90%成年人学琴只是为了弹些流行或古典小曲子，现在的电钢技术无论手感或是音色，已经能够满足这部分需求。\n像我用的卡西欧PX-S1100，88键数字化逐级配重，重锤感应和离键感应模拟真钢的力度和触感，192复音数，弹奏快速乐曲时也不会漏音丢音。\n同时它的音色从三角钢琴中采样，虽说比不上十几万的高端钢琴，但相比中低端传统钢琴，选电钢或许更有质价比💰\n最关键的是，电钢能静音！晚上一弹琴就被邻居投诉真的太烦了。电钢可以自由调节音量，戴上耳机🎧想弹到几点就弹到几点。\n	\n🔸【适合人群】新手刚入坑、不确定能否坚持、目标是弹流行和古典入门的成年人、小户型/租房党\n	\n2️⃣立式钢琴\n如果家里够大，希望给孩子从小打好古典基础，对演奏有较高要求的，还是建议选真钢。\n真钢又分立式与三角，立式琴触键较硬，适合锻炼基本功和手指机能。入手门槛相对电钢高一点，一两万能买到还过得去的国产琴，只是触键层次、音色表现力较为有限。\n	\n🔸【适合人群】明确走古典方向，琴童打基础、想系统学习古典乐的钢琴爱好者🎵\n	\n3️⃣三角钢琴\n如果说立式是24色的彩笔套装，那三角钢琴就是108色的。\n虽然都能画画，但三角琴能演绎出更丰富的渲染渐变，层次质感比立式琴更胜一筹。弹演奏级以上的曲子，会感觉更得心应手。\n🔸【适合人群】业余高级别、音乐专业人士。\n	\n当然真钢的缺点是：占地方、声音大扰民。搬一次500起，调律每年1~4次，立式300+，三角500+，累积下来也是一笔不小的开销💰\n	\n🌀总结：电钢/立式/三角各有优劣，不要抛开预算谈对比，拿几千块的电钢和几十万的真钢硬刚。\n建议💁🏻‍♀️如果平时弹点流行或感兴趣想试下水，电钢完全能满足需求。\n如果对古典曲目有追求，希望成为高阶选手的，还是需要真钢琴。\n当然最佳方案是「一机一电」，21点以后用电钢开谱、学新曲子，平时就用真钢锻炼手指能力、磨乐曲细节。\n	\n#电钢琴选购[话题]##电钢琴入门[话题]##钢琴选购[话题]##电钢琴推荐[话题]##卡西欧[话题]# #卡西欧电钢琴[话题]##PXS1100[话题]##卡西欧圆梦电钢琴[话题]##卡西欧电钢琴pxs1100[话题]#', '', 1733998620000, 1734058890000, '968', '436', '18', '92', '\"http://sns-web-i10.rednotecdn.com/202606101859/29f7862d2cf11895c370e7c7c03d85de/1040g00831ba7ine47q2g48hs6fql82blshsvoo8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101859/3b7a0066f130f1f695fc88643da0b064/1040g00831ba7ine47q0g48hs6fql82blfrbkej8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101859/ae8f4ac561c7b6c3454db2e47cae942c/1040g00831ba7ine47q1048hs6fql82blictkd60!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101859/517c5c05aa1d8f2742631b58846d1751/1040g00831ba7ine47q1g48hs6fql82blt2e4s28!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101859/bf005aa6c007aa140d22308e56c1701e/1040g00831ba7ine47q2048hs6fql82blf52f1so!nd_dft_wlteh_webp_3?src=A\"', '\"\\u7535\\u94a2\\u7434\\u9009\\u8d2d,\\u7535\\u94a2\\u7434\\u5165\\u95e8,\\u94a2\\u7434\\u9009\\u8d2d,\\u7535\\u94a2\\u7434\\u63a8\\u8350,\\u5361\\u897f\\u6b27,\\u5361\\u897f\\u6b27\\u7535\\u94a2\\u7434,PXS1100,\\u5361\\u897f\\u6b27\\u5706\\u68a6\\u7535\\u94a2\\u7434,\\u5361\\u897f\\u6b27\\u7535\\u94a2\\u7434pxs1100\"', 'https://www.xiaohongshu.com/explore/675aaaba000000000600ca85?xsec_token=ABS1fcJQoSU5ZQCLjQ4p66NohHswThskZMAOmbzqCGanY=&xsec_source=pc_search', '雅马哈 YDP165 性价比', 'ABS1fcJQoSU5ZQCLjQ4p66NohHswThskZMAOmbzqCGanY=');
INSERT INTO `xhs_note` VALUES (149, '5a71d879e8ac2b105ff703f7', '章兮兮', 'https://sns-avatar-qc.xhscdn.com/avatar/1040g2jo30nj5mv927kdg4a16qpc7i0vngr9cl90', '', 1781089189567, 1781089189567, '669f17df000000000a0068da', 'normal', '新手小白选钢琴', '今天和大家分享，我这个新手小白最终选定卡哇伊kdp120.这架电钢琴的心路历程\n1，首先是，了解钢琴和电钢琴\n电钢琴音色，手感这些不及真钢，但是对于新手小白，初学者来说，够用了。价格实惠，空间要求没那么高。钢琴音色，手感，外观都更好，但是他占空间，价格昂贵\n毫不犹豫，我选电钢\n2，其次，我卡预算。我最开始的预算是2-3000元\n这个预算中性价比高的钢琴主要有雅马哈p-145/罗兰fp-18，卡哇伊，卡西欧（因为新手小白也不太懂，所以直接看的几个大品牌）这个价位，基本就这几款比较合适了，我还是倾向于选择大品牌\n3，然后就是对品牌的了解\n雅马哈：音色明亮\n罗兰：琴键偏重\n卡哇伊：低音偏闷\n卡西欧：便携式为主\n4，选购电钢的转折点\n看了太多小伙伴们的攻略，对琴的要求我也提高了。又想音色好，又想手感好。甚至外观也很纠结。所以我提高了预算4000\n在这个预算中，使我最终下决定的是外形，想要带盖的，一是防止落灰，再是，好看，看起来更像钢琴，所以最后我 选择了kawai-KDP120', '', 1721702368000, 1721702368000, '815', '589', '108', '92', '\"http://sns-web-i10.rednotecdn.com/202606101859/4c4334f7b1eb4ce8637e9160d1f9d70f/1040g2sg315j1t211gud04a16qpc7i0vnm5us6j8!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101859/25bd48a2b731fdfde020bdeeb7c536a8/1040g2sg315j1t211gucg4a16qpc7i0vnckkt2t0!nd_dft_wlteh_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101859/4e4f135c5e4ee14ef3aa13f115795049/1040g2sg315j1t211gubg4a16qpc7i0vnp7udp1g!nd_dft_wgth_webp_3?src=A,http://sns-web-i10.rednotecdn.com/202606101859/43f383569d362a48c2af9be575a1c843/1040g2sg315j1t211gub04a16qpc7i0vnobk8h18!nd_dft_wgth_webp_3?src=A\"', '\"\"', 'https://www.xiaohongshu.com/explore/669f17df000000000a0068da?xsec_token=AB0-X7iiPv0VFDdxAYgiw30gMJrtjXudx8gHr21KG-9dQ=&xsec_source=pc_search', '雅马哈 YDP165 性价比', 'AB0-X7iiPv0VFDdxAYgiw30gMJrtjXudx8gHr21KG-9dQ=');
